// ─── START: components/device_wizard.js ───
class DeviceWizard {
  /**
   * @param {{hass:object, initialDeviceId?:string, onClose:Function, onSaved:Function}} opts
   */
  constructor({ hass, initialDeviceId, initialGroupId, onClose, onSaved }) {
    this.hass = hass;
    this.initialDeviceId = initialDeviceId || null;
    this.initialGroupId = initialGroupId || null;
    this.directMode = !!(this.initialDeviceId || this.initialGroupId);
    this.onClose = onClose;
    this.onSaved = onSaved;

    this.step = 0; // 0=Gerät, 1=Details, 2=Kanäle, 3=Prüfen
    this.steps = ['Gerät', 'Details', 'Kanäle', 'Prüfen'];

    this.devices = [];
    this.entities = [];
    this.areas = [];
    this.configuredDevices = {};
    this.categories = {};

    this.selectedDevice = null;
    this.customName = '';
    this.selectedAreaId = '';
    this.selectedCategory = 'schalter';
    this.renameInHA = true;
    this.forceOwnRow = false;

    // Channels / sub-entities
    this.channels = []; // [{ entity_id, enabled, name, category, power, energy, presence_simulation, unique_id }]
    this.primaryEntityId = '';
    this.powerEntityId = '';
    this.energyEntityId = '';

    this.searchQuery = '';
    this.preFilterMode = null; // null | 'room' | 'protocol' | 'all'
    this.selectedAreaFilter = '__all__';
    this.protocolFilter = 'all'; // 'all' | 'zigbee' | 'matter' | 'wifi_other'
    this.statusFilter = 'unconfigured'; // 'unconfigured' | 'all' | 'configured'
    this.selectedDevices = new Set();
    this._expandedDeviceChannels = new Set();
    this.groups = {};
    this.hybrids = {};
    this.hybridProposals = [];
    this.hybridSettings = { preferred_protocol: 'zigbee' };
    this.hiddenHybridDeviceIds = new Set();
    this._hybridPreferredProtocol = '';
    this._deviceMap = new Map();

    this.isCelebration = false;
    this._dropdowns = [];

    this._build();
    this._load();
  }

  destroy() {
    this._cleanupDropdowns();
    this.el?.remove();
  }

  _closeWizard() {
    this._cleanupDropdowns();
    this.onClose?.();
  }

  _build() {
    this.body = h('div', { class: 'dialog-body' });
    this.stepBar = h('div', { class: 'wizard-steps' });
    this.selectionSlot = h('div', { class: 'wizard-selection-slot' });
    this.foot = h('div', { class: 'dialog-foot' });

    this.dialog = h('div', { class: 'dialog', role: 'dialog', 'aria-label': 'Gerät einrichten', hidden: !!this.initialGroupId },
      h('div', { class: 'dialog-head' },
        icon('mdi:plus-circle-outline'),
        h('h2', {}, 'Gerät einrichten'),
        h('button', { class: 'icon-btn', 'aria-label': 'Schließen', onClick: () => this._closeWizard() }, icon('mdi:close'))),
      this.stepBar,
      this.body,
      this.selectionSlot,
      this.foot);

    this.el = h('div', { class: 'overlay', onClick: (e) => { if (e.target === this.el) this._closeWizard(); } }, this.dialog);
  }

  async _load({ preserveStep0 = false } = {}) {
    this.body.replaceChildren(h('div', { class: 'empty' }, icon('mdi:loading'), h('div', { style: { marginTop: '8px' } }, 'Lade Geräte')));
    try {
      const [devs, ents, areas, setup, dash, hybDisc] = await Promise.all([
        this.hass.callWS({ type: 'config/device_registry/list' }),
        this.hass.callWS({ type: 'config/entity_registry/list' }),
        this.hass.callWS({ type: 'config/area_registry/list' }),
        this.hass.callWS({ type: 'smarthome_companion/devices/get' }).catch(() => ({ devices: {}, categories: {} })),
        this.hass.callWS({ type: 'smarthome_companion/dashboard/get', edit: true }).catch(() => null),
        this.hass.callWS({ type: 'smarthome_companion/hybrids/discover' }).catch(() => ({ proposals: [] })),
      ]);
      this.devices = devs || [];
      this.entities = ents || [];
      this.areas = areas || [];
      this._deviceMap = new Map(this.devices.map((d) => [d.id, d]));
      this.configuredDevices = setup.devices || {};
      this.categories = setup.categories || {};
      this.groups = setup.groups || {};
      this.hybrids = hybDisc?.hybrids || setup.hybrids || {};
      this.hybridProposals = Array.isArray(hybDisc?.proposals) ? hybDisc.proposals : [];
      this.hybridSettings = hybDisc?.hybrid_settings || setup.hybrid_settings || { preferred_protocol: 'zigbee' };
      this.hiddenHybridDeviceIds = new Set(setup.hidden_hybrid_device_ids || []);
      this._dashboardRooms = dash?.layout?.rooms || [];
      this._dashboardConfig = dash?.config || {};

      if (!preserveStep0 && this.initialDeviceId) {
        const parsed = parseChannelKey(this.initialDeviceId);
        const lookupId = parsed.deviceId || parsed.entityId || this.initialDeviceId;
        const candidates = this._getSelectableCandidates();
        let target = candidates.find((d) => d.id === lookupId) || this.devices.find((d) => d.id === lookupId);
        if (!target && parsed.entityId) {
          target = candidates.find((d) => d.isVirtualEntity && d.entity_id === parsed.entityId);
          if (!target) {
            const ent = this.entities.find((e) => e.entity_id === parsed.entityId);
            if (ent?.device_id) {
              target = this.devices.find((d) => d.id === ent.device_id);
            }
          }
        }
        if (!target) {
          target = candidates.find((d) => d.isVirtualEntity && (d.id === this.initialDeviceId || d.entity_id === lookupId));
          if (!target) {
            const ent = this.entities.find((e) => e.entity_id === lookupId);
            if (ent?.device_id) {
              target = this.devices.find((d) => d.id === ent.device_id);
            }
          }
        }
        if (target) {
          this.selectedDevice = target;
          this._initDevice();
          this.step = 1;
        }
      }

      if (!preserveStep0 && this.initialGroupId && this.groups?.[this.initialGroupId]) {
        this.dialog.hidden = true;
        this._openGroupModal(this.groups[this.initialGroupId], true);
        return;
      }

      this._render();
    } catch (err) {
      this.body.replaceChildren(h('div', { class: 'empty' }, icon('mdi:alert'), h('div', {}, `Ladefehler: ${err.message || err}`)));
    }
  }

  _render() {
    this._cleanupDropdowns();
    this.selectionSlot.replaceChildren();
    if (this.body) this.body.scrollTop = 0;
    if (this.isCelebration) {
      this._renderCelebration();
      return;
    }
    const curCat = DEVICE_CATEGORIES.find((c) => c.id === this.selectedCategory) || DEVICE_CATEGORIES[0];
    const catColor = (this.step > 0 && curCat?.color) ? curCat.color : '#2196F3';
    this.dialog.style.setProperty('--hero-color', catColor);

    this._renderSteps();
    this._renderBody();
    this._renderFoot();
  }

  _cleanupDropdowns() {
    this._dropdowns.forEach((d) => d.destroy?.());
    this._dropdowns = [];
  }

  _renderSteps() {
    this.stepBar.hidden = false;
    this.stepBar.replaceChildren(...this.steps.map((name, i) => {
      const el = h('div', { class: 'wizard-step' },
        h('div', {}, `${i + 1}. ${name}`),
        h('div', { class: 'wizard-bar' }));
      if (i === this.step) el.dataset.active = '';
      else if (i < this.step) el.dataset.done = '';
      return el;
    }));
  }

  _renderFoot() {
    this.foot.hidden = false;
    const isFirst = this.step === 0;
    const isLast = this.step === this.steps.length - 1;
    const isConfigured = !!(this.selectedDevice && this.configuredDevices[this.selectedDevice.id]);

    const leftActions = [];
    if (isFirst || (this.initialDeviceId && this.step === 1)) {
      leftActions.push(h('button', { class: 'btn', onClick: () => this._closeWizard() }, 'Abbrechen'));
      if (!isFirst && isConfigured) {
        leftActions.push(h('button', {
          class: 'btn danger',
          title: 'Einrichtung aufheben',
          onClick: () => this._removeDevice(this.selectedDevice.id, this.customName),
        }, icon('mdi:delete-outline'), 'Entfernen'));
      }
    } else {
      leftActions.push(h('button', { class: 'btn', onClick: () => { this.step--; this._render(); } }, icon('mdi:chevron-left'), 'Zurück'));
      if (isConfigured) {
        leftActions.push(h('button', {
          class: 'btn danger',
          title: 'Einrichtung aufheben',
          onClick: () => this._removeDevice(this.selectedDevice.id, this.customName),
        }, icon('mdi:delete-outline'), 'Entfernen'));
      }
    }

    const rightActions = [];
    if (isFirst) {
      rightActions.push(h('button', {
        class: 'btn primary', disabled: !this.selectedDevice,
        onClick: () => { if (this.selectedDevice) { this._initDevice(); this.step = 1; this._render(); } },
      }, 'Weiter', icon('mdi:chevron-right')));
    } else if (!isLast) {
      rightActions.push(h('button', {
        class: 'btn primary',
        onClick: () => { this.step++; this._render(); },
      }, 'Weiter', icon('mdi:chevron-right')));
    } else {
      rightActions.push(h('button', {
        class: 'btn success', disabled: this._saving,
        onClick: () => this._save(),
      }, icon('mdi:check'), this._saving ? 'Speichert...' : 'Speichern'));
    }

    const leftWrap = h('div', { class: 'dialog-foot-actions' }, ...leftActions);
    const rightWrap = h('div', { class: 'dialog-foot-actions' }, ...rightActions);
    this.foot.replaceChildren(leftWrap, rightWrap);
  }

  async _removeDevice(deviceId, name) {
    const devName = name || this.customName || 'Gerät';
    const confirmed = await showConfirmDialog(this.el, {
      title: 'Einrichtung aufheben',
      message: `„${devName}“ entfernen? HA-Gerät bleibt bestehen.`,
      confirmLabel: 'Entfernen',
      cancelLabel: 'Abbrechen',
      danger: true,
    });
    if (!confirmed) return;

    try {
      const res = await this.hass.callWS({
        type: 'smarthome_companion/devices/remove',
        device_id: deviceId,
      });
      if (res?.save_failed) throw new Error('Löschen fehlgeschlagen');

      delete this.configuredDevices[deviceId];
      if (this.directMode) {
        this._cleanupDropdowns();
        this.onSaved(null);
        return;
      }
      if (this.selectedDevice?.id === deviceId) {
        this.selectedDevice = null;
        this.step = 0;
      }

      this._render();
      this.onSaved(null);
    } catch (err) {
      showToast(this.el, `Fehler: ${err.message || err}`, { error: true });
    }
  }

  _getConfiguredConfigForCandidate(d) {
    if (!d) return null;
    if (this.configuredDevices[d.id]) return this.configuredDevices[d.id];
    if (d.isVirtualEntity) {
      for (const [key, cfg] of Object.entries(this.configuredDevices)) {
        if (key.startsWith('entity:') && cfg?.entities?.primary === d.entity_id) {
          return cfg;
        }
      }
    }
    return null;
  }

  _getDeviceProtocol(d) {
    if (!d) return 'wifi_other';
    if (d._protocol) return d._protocol;
    const devEnts = d.isVirtualEntity
      ? (this.entities || []).filter((e) => e.entity_id === d.entity_id)
      : (this.entities || []).filter((e) => e.device_id === d.id);
    d._protocol = classifyDeviceProtocol(d, devEnts, this._deviceMap);
    return d._protocol;
  }

  _getSelectableCandidates() {
    const devMap = this._deviceMap || new Map((this.devices || []).map((d) => [d.id, d]));
    const realDevices = (this.devices || []).filter((d) => !this.hiddenHybridDeviceIds?.has(d.id) && this._isCandidateDevice(d));
    const realDeviceIds = new Set(realDevices.map((d) => d.id));
    const bridgeDeviceIds = new Set(
      (this.devices || [])
        .filter((d) => isBridgeOrCoordinator(d, (this.entities || []).filter((e) => e.device_id === d.id)))
        .map((d) => d.id),
    );

    const virtualLightGroups = [];
    const seenVirtual = new Set();
    const seenEntityIds = new Set();

    for (const e of (this.entities || [])) {
      if (!e || !e.entity_id || e.disabled_by) continue;
      if (isOwnIntegrationEntity(e)) continue;
      if (e.entity_category === 'config' || e.entity_category === 'diagnostic') continue;
      if (IGNORED_PLATFORMS.has(String(e.platform || '').toLowerCase())) continue;
      if (domainOf(e.entity_id) !== 'light') continue;

      const parentDev = e.device_id ? devMap.get(e.device_id) : null;
      const st = this.hass?.states?.[e.entity_id];
      const hasMemberAttr = Array.isArray(st?.attributes?.entity_id) && st.attributes.entity_id.length > 0;
      const isAttachedToBridge = !!e.device_id && bridgeDeviceIds.has(e.device_id);
      const isZ2mGroupDevice = !!parentDev && (
        /zigbee2mqtt/i.test(`${parentDev.manufacturer || ''} ${parentDev.model || ''}`)
        && /\bgroup\b/i.test(`${parentDev.model || ''} ${parentDev.name || ''}`)
      );
      const isUnattachedGroup = !e.device_id || e.platform === 'group' || hasMemberAttr;
      if (!isUnattachedGroup && !isAttachedToBridge && !isZ2mGroupDevice) continue;
      // Avoid duplicate if its parent non-bridge device is already listed
      if (e.device_id && realDeviceIds.has(e.device_id) && !isZ2mGroupDevice) continue;

      const vid = `entity:${e.entity_id}`;
      if (seenVirtual.has(vid)) continue;
      seenVirtual.add(vid);
      seenEntityIds.add(e.entity_id);

      const stName = st?.attributes?.friendly_name;
      const plat = String(e.platform || '').toLowerCase();
      const parentHay = parentDev ? `${parentDev.manufacturer || ''} ${parentDev.model || ''} ${parentDev.name || ''}`.toLowerCase() : '';
      const isZha = plat === 'zha' || /zha/.test(parentHay);
      const isZ2m = (plat === 'mqtt' && (/zigbee|z2m/.test(parentHay) || isZ2mGroupDevice)) || /zigbee2mqtt/.test(parentHay);
      const isDeconz = plat === 'deconz' || /deconz/.test(parentHay);
      const isHue = plat === 'hue' || /hue/.test(parentHay);
      const isZigbeeGroup = isZha || isZ2m || isDeconz || isHue || /zigbee/i.test(String(stName || ''));
      const mfgLabel = isZha ? 'ZHA Gruppe' : (isZ2m ? 'Zigbee2MQTT Gruppe' : (e.platform ? `${String(e.platform).toUpperCase()} Gruppe` : 'Lichtgruppe'));

      virtualLightGroups.push({
        id: vid,
        isVirtualEntity: true,
        entity_id: e.entity_id,
        platform: e.platform || '',
        name: e.name || e.original_name || stName || e.entity_id,
        name_by_user: e.name || null,
        area_id: e.area_id || parentDev?.area_id || null,
        manufacturer: mfgLabel,
        model: isZigbeeGroup ? 'Zigbee Gruppe' : 'Lichtgruppe',
        identifiers: [],
        _protocol: isZigbeeGroup ? 'zigbee' : 'wifi_other',
      });
    }

    // Fallback: runtime light.* groups in hass.states without entity registry entry
    if (this.hass?.states) {
      for (const [eid, st] of Object.entries(this.hass.states)) {
        if (!eid.startsWith('light.') || seenEntityIds.has(eid)) continue;
        if (!Array.isArray(st?.attributes?.entity_id) || !st.attributes.entity_id.length) continue;
        const vid = `entity:${eid}`;
        if (seenVirtual.has(vid)) continue;
        seenVirtual.add(vid);
        virtualLightGroups.push({
          id: vid,
          isVirtualEntity: true,
          entity_id: eid,
          platform: 'group',
          name: st.attributes?.friendly_name || eid,
          name_by_user: null,
          area_id: null,
          manufacturer: 'Lichtgruppe',
          model: 'Lichtgruppe',
          identifiers: [],
          _protocol: 'wifi_other',
        });
      }
    }

    return [...realDevices, ...virtualLightGroups];
  }

  _isCandidateDevice(d) {
    if (!d || d.disabled_by) return false;
    if (this.hiddenHybridDeviceIds?.has(d.id)) return false;
    const isHybrid = isHybridMasterDevice(d);
    const devAllEnts = (this.entities || []).filter((e) => e.device_id === d.id && !e.disabled_by);
    if (!isHybrid) {
      if (isBridgeOrCoordinator(d, devAllEnts)) return false;
      if (d.entry_type === 'service') return false;
      if (isIrrelevantDeviceOrIntegration(d, devAllEnts)) return false;
    }

    const devEntities = devAllEnts.filter(
      (e) => (isHybrid || !isOwnIntegrationEntity(e))
        && e.entity_category !== 'config'
        && e.entity_category !== 'diagnostic'
        && !IGNORED_PLATFORMS.has(String(e.platform || '').toLowerCase()),
    );
    const controllable = devEntities.filter((e) => isControllableActuator(e, { allowOwnHybrid: isHybrid }));
    const relevantSensors = devEntities.filter((e) => {
      const dom = domainOf(e.entity_id);
      if (dom !== 'sensor' && dom !== 'binary_sensor') return false;
      const st = this.hass?.states?.[e.entity_id];
      const dc = String(st?.attributes?.device_class || '').toLowerCase();
      const hay = `${e.entity_id} ${e.name || e.original_name || ''}`.toLowerCase();
      if (/(?:cpu|processor|memory|ram_usage|disk_|swap_|load_1m|load_5m|load_15m|container_|docker|uptime|ip_address|external_ip|bytes_received|bytes_sent|link_status)/.test(hay)) {
        return false;
      }
      if (ROOM_SENSOR_DEVICE_CLASSES.has(dc)) return true;
      return true;
    });
    if (!controllable.length && !relevantSensors.length) {
      const disabledUserActuators = (this.entities || []).filter(
        (e) => e.device_id === d.id
          && e.disabled_by === 'user'
          && !isOwnIntegrationEntity(e)
          && e.entity_category !== 'config'
          && e.entity_category !== 'diagnostic'
          && !IGNORED_PLATFORMS.has(String(e.platform || '').toLowerCase())
          && isControllableActuator(e, { allowDisabledUser: true }),
      );
      if (disabledUserActuators.length > 0) return true;
      return false;
    }
    return true;
  }

  // ═══════════════ STEP 0: Gerät auswählen ═══════════════
  _renderStep0() {
    const candidates = this._getSelectableCandidates();
    const areaMap = new Map(this.areas.map((a) => [a.area_id, a.name]));

    const searchInput = h('input', {
      type: 'text', placeholder: 'Gerät, Raum, Zigbee oder WLAN suchen', value: this.searchQuery,
      onInput: (e) => {
        this.searchQuery = e.target.value.toLowerCase().trim();
        if (this.searchQuery && this.preFilterMode === null) {
          this.preFilterMode = 'all';
          this._renderStep0();
          // Restore focus cleanly after DOM replacement
          setTimeout(() => this.body.querySelector('.search-bar input')?.focus(), 0);
        } else {
          this._updateDeviceList();
        }
      },
    });
    const searchWrap = h('div', { class: 'search-bar' }, icon('mdi:magnify'), searchInput);

    if (this.preFilterMode === null && !this.searchQuery) {
      const zigbeeCount = candidates.filter((d) => this._getDeviceProtocol(d) === 'zigbee').length;
      const matterCount = candidates.filter((d) => this._getDeviceProtocol(d) === 'matter').length;
      const wifiCount = candidates.length - zigbeeCount - matterCount;
      const roomIds = new Set(candidates.map((d) => d.area_id || '__none__'));
      const protoDesc = matterCount > 0 ? 'Zigbee · Matter · WLAN' : 'Zigbee vs. WLAN';
      const protoCountText = matterCount > 0
        ? `${zigbeeCount} Zigbee · ${matterCount} Matter · ${wifiCount} WLAN`
        : `${zigbeeCount} Zigbee · ${wifiCount} WLAN`;

      const mkPrefilterCard = (mode, ic, title, sub, meta) => h('button', {
        type: 'button',
        class: 'wizard-prefilter-card',
        onClick: () => {
          this.preFilterMode = mode;
          if (mode === 'room') this.selectedAreaFilter = '__all__';
          if (mode === 'protocol') this.protocolFilter = 'all';
          this._renderStep0();
        },
      },
      h('div', { class: 'wizard-prefilter-icon' }, icon(ic)),
      h('div', { class: 'wizard-prefilter-title' }, title),
      h('div', { class: 'wizard-prefilter-sub' }, sub),
      meta ? h('span', { class: 'badge-tag' }, meta) : null);

      const grid = h('div', { class: 'wizard-prefilter-grid' },
        mkPrefilterCard('room', 'mdi:floor-plan', 'Nach Raum', 'Nach Home-Assistant-Bereichen filtern', `${roomIds.size} ${roomIds.size === 1 ? 'Raum' : 'Räume'}`),
        mkPrefilterCard('protocol', 'mdi:zigbee', 'Nach Verbindung', protoDesc, protoCountText),
        mkPrefilterCard('all', 'mdi:devices', 'Alle unterstützten Geräte', 'Komplette bereinigte Geräteliste', `${candidates.length} Geräte`));

      const proposalsBox = (this.hybridProposals && this.hybridProposals.length > 0)
        ? h('div', { class: 'hybrid-proposals-section' },
          h('div', { style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px', flexWrap: 'wrap' } },
            h('div', { style: { display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '700', fontSize: '14px' } },
              icon('mdi:swap-horizontal-bold'),
              `Erkannte Hybrid-Geräte (${this.hybridProposals.length})`),
            h('span', { class: 'hint' }, '• Identische Hardware über mehrere Funkwege')),
          ...this.hybridProposals.map((p) => {
            const protoLabel = (p.protocols || []).map((pr) => (pr === 'zigbee' ? 'Zigbee' : pr === 'matter' ? 'Matter' : 'WLAN')).join(' + ');
            const confLabel = p.confidence === 'high' ? 'Sehr sicher' : 'Vorschlag';
            return h('div', { class: 'hybrid-proposal-card' },
              h('div', { style: { minWidth: '180px', flex: '1 1 220px' } },
                h('div', { style: { display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap', fontWeight: '600' } },
                  p.suggested_name || 'Hybrid-Gerät',
                  h('span', { class: 'badge-tag hybrid' }, protoLabel),
                  h('span', { class: 'badge-tag ok' }, confLabel)),
                h('div', { class: 'hint', style: { marginTop: '2px' } }, (p.reasons || []).join(' · '))),
              h('div', { style: { display: 'flex', gap: '6px', flexWrap: 'wrap' } },
                h('button', {
                  type: 'button',
                  class: 'btn secondary small',
                  onClick: async () => {
                    try {
                      await this.hass.callWS({ type: 'smarthome_companion/hybrids/dismiss_pair', pair_key: p.pair_key });
                    } catch (_) { /* non-fatal */ }
                    this.hybridProposals = this.hybridProposals.filter((x) => x.pair_key !== p.pair_key);
                    this._renderStep0();
                  },
                }, 'Verwerfen'),
                h('button', {
                  type: 'button',
                  class: 'btn primary small',
                  onClick: () => this._openHybridModal({ proposal: p }),
                }, icon('mdi:swap-horizontal-bold'), 'Als Hybrid verbinden')));
          }))
        : null;

      this.deviceListEl = h('div', { class: 'device-list' });
      this.selectionSlot.replaceChildren();
      this.body.replaceChildren(
        ...[
          searchWrap,
          proposalsBox,
          h('div', { class: 'section-title', style: { marginTop: '14px' } }, 'Geräteauswahl eingrenzen'),
          h('div', { class: 'hint' }, '• Vorfilter wählen oder direkt suchen\n• System- & Kalender-Dienste ausgeblendet'),
          grid,
        ].filter(Boolean),
      );
      return;
    }

    // Mode sub-navigation & sub-filters
    const modeBar = h('div', { class: 'wizard-filter-subbar' },
      h('button', {
        type: 'button',
        class: 'filter-chip',
        onClick: () => {
          this.preFilterMode = null;
          this.searchQuery = '';
          this._renderStep0();
        },
      }, icon('mdi:arrow-left'), ' Vorfilter'),
      ...[
        ['room', 'Nach Raum', 'mdi:floor-plan'],
        ['protocol', 'Zigbee / WLAN', 'mdi:zigbee'],
        ['all', 'Alle Geräte', 'mdi:devices'],
      ].map(([mId, mLabel, mIcon]) => h('button', {
        type: 'button',
        class: 'filter-chip',
        ...(this.preFilterMode === mId ? { 'data-active': '' } : {}),
        onClick: () => { this.preFilterMode = mId; this._renderStep0(); },
      }, icon(mIcon), ' ', mLabel)));

    let subFilterRow = null;
    if (this.preFilterMode === 'room') {
      const counts = new Map();
      for (const d of candidates) {
        const key = d.area_id || '__none__';
        counts.set(key, (counts.get(key) || 0) + 1);
      }
      const areaEntries = this.areas
        .filter((a) => counts.has(a.area_id))
        .map((a) => [a.area_id, `${a.name} (${counts.get(a.area_id)})`]);
      if (counts.has('__none__')) {
        areaEntries.push(['__none__', `Ohne Raum (${counts.get('__none__')})`]);
      }
      subFilterRow = h('div', { class: 'filter-chips', style: { marginBottom: '8px' } },
        ...[['__all__', `Alle Räume (${candidates.length})`], ...areaEntries].map(([aid, alabel]) => h('button', {
          type: 'button',
          class: 'filter-chip',
          ...(this.selectedAreaFilter === aid ? { 'data-active': '' } : {}),
          onClick: () => { this.selectedAreaFilter = aid; this._renderStep0(); },
        }, alabel)));
    } else if (this.preFilterMode === 'protocol') {
      const zigbeeCount = candidates.filter((d) => this._getDeviceProtocol(d) === 'zigbee').length;
      const matterCount = candidates.filter((d) => this._getDeviceProtocol(d) === 'matter').length;
      const wifiCount = candidates.length - zigbeeCount - matterCount;
      const protoChips = [
        ['all', `Alle (${candidates.length})`, 'mdi:devices'],
        ['zigbee', `Zigbee (${zigbeeCount})`, 'mdi:zigbee'],
        ...(matterCount > 0 ? [['matter', `Matter (${matterCount})`, 'mdi:hub']] : []),
        ['wifi_other', `WLAN (${wifiCount})`, 'mdi:wifi'],
      ];
      subFilterRow = h('div', { class: 'filter-chips', style: { marginBottom: '8px' } },
        ...protoChips.map(([pid, plabel, pIcon]) => h('button', {
          type: 'button',
          class: 'filter-chip',
          ...(this.protocolFilter === pid ? { 'data-active': '' } : {}),
          onClick: () => { this.protocolFilter = pid; this._renderStep0(); },
        }, icon(pIcon), ' ', plabel)));
    }

    const baseFiltered = this._getModeFilteredCandidates(candidates);
    const configuredCount = baseFiltered.filter((d) => !!this._getConfiguredConfigForCandidate(d)).length;
    const unconfiguredCount = baseFiltered.filter((d) => {
      const cfg = this._getConfiguredConfigForCandidate(d);
      if (!cfg) return true;
      return getPendingChannelsForDevice(d, this.entities, cfg).length > 0;
    }).length;
    const allCount = baseFiltered.length;

    const filterChips = h('div', { class: 'filter-chips' },
      ...[
        ['unconfigured', `Offen (${unconfiguredCount})`],
        ['configured', `Eingerichtet (${configuredCount})`],
        ['all', `Alle (${allCount})`],
      ].map(([id, label]) => h('button', {
        class: 'filter-chip', ...(id === this.statusFilter ? { 'data-active': '' } : {}),
        onClick: () => { this.statusFilter = id; this._renderStep0(); },
      }, label)));

    this.deviceListEl = h('div', { class: 'device-list' });
    this._updateDeviceList();

    this.body.replaceChildren(
      ...[searchWrap, modeBar, subFilterRow, filterChips, this.deviceListEl].filter(Boolean),
    );
  }

  _getModeFilteredCandidates(candidates) {
    return candidates.filter((d) => {
      if (this.preFilterMode === 'room' && this.selectedAreaFilter && this.selectedAreaFilter !== '__all__') {
        const key = d.area_id || '__none__';
        if (key !== this.selectedAreaFilter) return false;
      }
      if (this.preFilterMode === 'protocol' && this.protocolFilter && this.protocolFilter !== 'all') {
        if (this._getDeviceProtocol(d) !== this.protocolFilter) return false;
      }
      return true;
    });
  }

  _updateDeviceList() {
    const areaMap = new Map(this.areas.map((a) => [a.area_id, a.name]));
    const q = this.searchQuery;

    const filtered = this._getModeFilteredCandidates(this._getSelectableCandidates()).filter((d) => {
      const cfg = this._getConfiguredConfigForCandidate(d);
      const isConfigured = !!cfg;
      const pending = isConfigured ? getPendingChannelsForDevice(d, this.entities, cfg) : [];
      if (this.statusFilter === 'unconfigured' && isConfigured && pending.length === 0) return false;
      if (this.statusFilter === 'configured' && !isConfigured) return false;

      if (!q) return true;
      const name = (d.name_by_user || d.name || '').toLowerCase();
      const mfg = (d.manufacturer || '').toLowerCase();
      const model = (d.model || '').toLowerCase();
      const area = (areaMap.get(d.area_id) || '').toLowerCase();
      const entId = (d.entity_id || '').toLowerCase();
      const pRaw = this._getDeviceProtocol(d);
      const proto = pRaw === 'zigbee' ? 'zigbee' : (pRaw === 'matter' ? 'matter' : 'wlan');
      return name.includes(q) || mfg.includes(q) || model.includes(q) || area.includes(q) || entId.includes(q) || proto.includes(q);
    });

    const hasAnyGroups = this.statusFilter !== 'unconfigured' && Object.values(this.groups).some((g) => {
      if (!q) return true;
      return (g.name || '').toLowerCase().includes(q) || (areaMap.get(g.area_id) || '').toLowerCase().includes(q);
    });

    if (!filtered.length && !hasAnyGroups) {
      let configuredMatchCount = 0;
      if (q && this.statusFilter === 'unconfigured') {
        const modeCandidates = this._getModeFilteredCandidates(this._getSelectableCandidates());
        for (const d of modeCandidates) {
          if (!this._getConfiguredConfigForCandidate(d)) continue;
          const hay = `${d.name_by_user || d.name || ''} ${d.manufacturer || ''} ${d.model || ''} ${areaMap.get(d.area_id) || ''} ${d.entity_id || ''}`.toLowerCase();
          if (hay.includes(q)) configuredMatchCount++;
        }
        for (const g of Object.values(this.groups)) {
          if (`${g.name || ''} ${areaMap.get(g.area_id) || ''}`.toLowerCase().includes(q)) configuredMatchCount++;
        }
      }
      this.deviceListEl.replaceChildren(h('div', { class: 'empty' },
        icon('mdi:devices'),
        h('div', {}, 'Keine Geräte'),
        configuredMatchCount > 0 ? h('div', { style: { marginTop: '10px' } },
          h('button', {
            type: 'button',
            class: 'btn secondary small',
            onClick: () => { this.statusFilter = 'all'; this._renderStep0(); },
          }, `${configuredMatchCount} eingerichtete Treffer anzeigen`)) : null));
      this.selectionSlot.replaceChildren();
      return;
    }

    const groups = new Map();
    for (const d of filtered) {
      const areaName = areaMap.get(d.area_id) || 'Ohne Raum';
      if (!groups.has(areaName)) groups.set(areaName, []);
      groups.get(areaName).push(d);
    }

    // Also include rooms from groups (ONLY when filter shows configured/all and matches or no query)
    if (this.statusFilter !== 'unconfigured') {
      for (const g of Object.values(this.groups)) {
        if (q && !(g.name || '').toLowerCase().includes(q) && !(areaMap.get(g.area_id) || '').toLowerCase().includes(q)) continue;
        const areaName = areaMap.get(g.area_id) || 'Ohne Raum';
        if (!groups.has(areaName)) groups.set(areaName, []);
      }
    }

    const sortedGroupNames = Array.from(groups.keys()).sort((a, b) => {
      if (a === 'Ohne Raum') return 1;
      if (b === 'Ohne Raum') return -1;
      return a.localeCompare(b);
    });

    const toggleSelectId = (id) => {
      preserveScroll(this.body, () => {
        if (this.selectedDevices.has(id)) this.selectedDevices.delete(id);
        else this.selectedDevices.add(id);
        this._updateDeviceList();
      });
    };

    const sections = sortedGroupNames.map((areaName) => {
      const devs = groups.get(areaName) || [];
      devs.sort((a, b) => {
        const nameA = (a.name_by_user || a.name || '').toLowerCase();
        const nameB = (b.name_by_user || b.name || '').toLowerCase();
        return nameA.localeCompare(nameB);
      });

      const roomGroups = this.statusFilter === 'unconfigured'
        ? []
        : Object.values(this.groups).filter((g) => {
          if (q && !(g.name || '').toLowerCase().includes(q) && !(areaMap.get(g.area_id) || '').toLowerCase().includes(q)) return false;
          const aName = areaMap.get(g.area_id) || 'Ohne Raum';
          return aName === areaName;
        });

      const groupCards = roomGroups.map((g) => createGroupCard({
        group: g,
        selectable: true,
        isSelected: this.selectedDevices.has(g.id),
        onToggleSelect: () => toggleSelectId(g.id),
        onCardClick: () => toggleSelectId(g.id),
        onEdit: () => this._openGroupModal(g),
        onDelete: () => this._removeGroup(g.id, g.name),
      }));

      const devCards = devs.flatMap((d) => {
        const name = d.name_by_user || d.name || 'Gerät';
        return createWizardDeviceElements({
          device: d,
          entities: this.entities,
          configuredCfg: this._getConfiguredConfigForCandidate(d),
          isSelected: this.selectedDevices.has(d.id),
          isExpanded: this._expandedDeviceChannels.has(d.id),
          selectedIds: this.selectedDevices,
          onToggleSelect: () => toggleSelectId(d.id),
          onToggleChannelSelect: (chKey) => toggleSelectId(chKey),
          onToggleExpand: () => {
            preserveScroll(this.body, () => {
              if (this._expandedDeviceChannels.has(d.id)) this._expandedDeviceChannels.delete(d.id);
              else this._expandedDeviceChannels.add(d.id);
              this._updateDeviceList();
            });
          },
          onConfigure: () => {
            this.selectedDevice = d;
            this._initDevice();
            this.step = 1;
            this._render();
          },
          onRemove: () => this._removeDevice(d.id, name),
          onCardClick: () => {
            if (this.selectedDevices.size > 0) {
              toggleSelectId(d.id);
              return;
            }
            this.selectedDevice = d;
            this._initDevice();
            this.step = 1;
            this._render();
          },
        });
      });

      const totalCount = groupCards.length + devs.length;
      const roomArea = this.areas.find((a) => a.name === areaName);
      const roomIcon = roomArea ? this._getRoomIcon(roomArea) : null;
      return createDeviceRoomSection(areaName, [...groupCards, ...devCards], totalCount, roomIcon);
    });

    this.deviceListEl.replaceChildren(...sections);

    if (this.selectedDevices.size > 0) {
      const selectedList = Array.from(this.selectedDevices);
      const names = selectedList.map((id) => {
        if (this.groups[id]) return this.groups[id].name;
        if (id.startsWith('d:')) {
          const parsed = parseChannelKey(id);
          const ent = this.entities.find((e) => e.entity_id === parsed.entityId);
          return ent?.name || ent?.original_name || parsed.entityId || id;
        }
        const d = this._getSelectableCandidates().find((dev) => dev.id === id) || this.devices.find((dev) => dev.id === id);
        return d?.name_by_user || d?.name || id;
      }).join(', ');

      const isSingle = selectedList.length === 1;
      const singleId = selectedList[0];
      const isSingleGroup = isSingle && !!this.groups[singleId];
      const allGroups = selectedList.length >= 2 && selectedList.every((id) => !!this.groups[id]);
      const hasExistingGroups = Object.keys(this.groups).length > 0;

      const buttons = [
        h('button', {
          class: 'btn secondary small',
          type: 'button',
          onClick: () => {
            preserveScroll(this.body, () => {
              this.selectedDevices.clear();
              this._updateDeviceList();
            });
          },
        }, 'Abbrechen'),
      ];

      if (isSingleGroup) {
        buttons.push(
          h('button', {
            class: 'btn secondary small',
            type: 'button',
            onClick: () => this._openGroupModal(this.groups[singleId]),
          }, icon('mdi:pencil'), 'Bearbeiten'),
          h('button', {
            class: 'btn danger small',
            type: 'button',
            onClick: () => this._removeGroup(singleId, this.groups[singleId].name),
          }, icon('mdi:delete-outline'), 'Auflösen')
        );
      } else if (isSingle) {
        if (hasExistingGroups) {
          buttons.push(
            h('button', {
              class: 'btn primary small',
              type: 'button',
              onClick: () => this._openAddToGroupModal(selectedList),
            }, icon('mdi:plus-box-multiple'), '+ Gruppe')
          );
        }
        buttons.push(
          h('button', {
            class: 'btn primary small',
            type: 'button',
            disabled: true,
            title: 'Mind. 2 Elemente wählen',
            style: { opacity: '0.45', cursor: 'not-allowed' },
          }, icon('mdi:lightbulb-group'), 'Gruppe (ab 2)')
        );
      } else {
        buttons.push(
          h('button', {
            class: 'btn primary small',
            type: 'button',
            onClick: () => this._openGroupModal(),
          }, icon(allGroups ? 'mdi:folder-multiple' : 'mdi:lightbulb-group'),
            h('span', { class: 'btn-label-desktop' }, allGroups ? 'Hauptgruppe' : 'Gruppieren'),
            h('span', { class: 'btn-label-mobile' }, allGroups ? 'Hauptgruppe' : 'Gruppe'))
        );
        if (hasExistingGroups && !allGroups) {
          buttons.push(
            h('button', {
              class: 'btn secondary small',
              type: 'button',
              onClick: () => this._openAddToGroupModal(selectedList),
            }, icon('mdi:plus-box-multiple'),
              h('span', { class: 'btn-label-desktop' }, '+ Gruppe'),
              h('span', { class: 'btn-label-mobile' }, '+ Gruppe'))
          );
        }
        const selectedDevs = selectedList.map((id) => this._deviceMap?.get(id)).filter(Boolean);
        const canPairHybrid = selectedList.length >= 2 && selectedList.length <= 3
          && !allGroups
          && selectedDevs.length === selectedList.length
          && selectedDevs.every((d) => !d.isVirtualEntity && !isHybridMasterDevice(d) && !this.groups[d.id]);
        if (canPairHybrid) {
          buttons.push(
            h('button', {
              class: 'btn secondary small',
              type: 'button',
              onClick: () => this._openHybridModal({ deviceIds: selectedList }),
            }, icon('mdi:swap-horizontal-bold'),
              h('span', { class: 'btn-label-desktop' }, 'Hybrid koppeln'),
              h('span', { class: 'btn-label-mobile' }, 'Hybrid'))
          );
        }
      }

      this.selectionSlot.replaceChildren(
        h('div', { class: 'selection-action-bar' },
          h('div', { class: 'sel-info' },
            h('span', { class: 'sel-count' }, `${selectedList.length} ausgewählt`),
            h('span', { class: 'sel-names' }, names)),
          h('div', { class: 'sel-buttons' }, ...buttons))
      );
    } else {
      this.selectionSlot.replaceChildren();
    }
  }

  _openAddToGroupModal(selectedIds) {
    const existingGroups = Object.values(this.groups);
    if (!existingGroups.length) return;

    const overlay = h('div', { class: 'overlay', style: { zIndex: '1200' } });
    const groupCards = existingGroups.map((g) => {
      const cat = DEVICE_CATEGORIES.find((c) => c.id === g.category);
      const catColor = cat?.color || '#ffc107';
      const a = this.areas.find((ar) => ar.area_id === g.area_id);
      const roomTxt = a ? ` · ${a.name}` : '';
      return h('div', {
        class: 'device-card group-card',
        style: { marginBottom: '8px' },
        onClick: async () => {
          const currentChildren = g.children || [];
          const updatedChildren = Array.from(new Set([...currentChildren, ...selectedIds]));
          try {
            await this.hass.callWS({
              type: 'smarthome_companion/groups/save',
              group: {
                ...g,
                children: updatedChildren,
              },
            });
            overlay.remove();
            this.selectedDevices.clear();
            this._load();
            this.onSaved?.(null);
          } catch (err) {
            showToast(this.el, `Fehler: ${err.message || err}`, { error: true });
          }
        },
      },
      h('div', { class: 'd-icon', style: { color: catColor } }, icon(g.icon || 'mdi:lightbulb-group')),
      h('div', { class: 'd-info' },
        h('div', { class: 'd-name' }, g.name),
        h('div', { class: 'd-meta' },
          h('span', { class: 'badge-tag category', style: { '--badge-cat-color': catColor } },
            icon('mdi:lightbulb-group'), `Gruppe (${g.children?.length || 0})${roomTxt}`))),
      h('div', { style: { display: 'flex', alignItems: 'center' } }, icon('mdi:chevron-right')));
    });

    const dialog = h('div', { class: 'dialog group-modal-dialog' },
      h('div', { class: 'dialog-head' },
        icon('mdi:plus-box-multiple'),
        h('h2', {}, 'Zu Gruppe'),
        h('button', { class: 'icon-btn', 'aria-label': 'Schließen', onClick: () => overlay.remove() }, icon('mdi:close'))),
      h('div', { class: 'dialog-body', style: { display: 'flex', flexDirection: 'column', gap: '8px' } },
        h('div', { class: 'hint' }, `${selectedIds.length} Element(e) hinzufügen`),
        ...groupCards),
      h('div', { class: 'dialog-foot' },
        h('div', { class: 'dialog-foot-actions' },
          h('button', { class: 'btn', onClick: () => overlay.remove() }, 'Abbrechen')))
    );
    overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.remove(); });
    overlay.appendChild(dialog);
    this.el.appendChild(overlay);
  }

  _openGroupModal(existingGroup = null, isDirect = false) {
    let selectedIds = existingGroup ? [...(existingGroup.children || [])] : Array.from(this.selectedDevices);
    if (!existingGroup && selectedIds.length < 2) return;
    const isMultiGroup = !existingGroup && selectedIds.some((id) => !!this.groups[id]);

    let groupName = existingGroup ? existingGroup.name : (isMultiGroup ? 'Hauptgruppe' : 'Lichtgruppe');
    let defaultArea = existingGroup ? (existingGroup.area_id || '') : '';
    let detectedCat = existingGroup ? (existingGroup.category || 'leuchte') : 'leuchte';

    if (!existingGroup) {
      for (const id of selectedIds) {
        if (this.groups[id]?.area_id) { defaultArea = this.groups[id].area_id; }
        else if (id.startsWith('d:')) {
          const parsed = parseChannelKey(id);
          const dev = this.devices.find((d) => d.id === parsed.deviceId);
          if (dev?.area_id) defaultArea = dev.area_id;
        } else {
          const dev = this.devices.find((d) => d.id === id);
          if (dev?.area_id) defaultArea = dev.area_id;
          else {
            const ent = this.entities.find((e) => (e.device_id === id || e.entity_id === id) && e.area_id);
            if (ent?.area_id) defaultArea = ent.area_id;
          }
        }
        if (defaultArea) break;
      }

      for (const id of selectedIds) {
        if (this.groups[id]?.category) { detectedCat = this.groups[id].category; break; }
        const cfg = this.configuredDevices[id];
        if (cfg?.category) { detectedCat = cfg.category; break; }
      }
    }

    let selectedArea = defaultArea;
    let selectedCat = detectedCat;

    const overlay = h('div', { class: 'overlay', style: { zIndex: '1200' } });
    const nameInput = h('input', {
      type: 'text',
      class: 'dialog-input',
      value: groupName,
      placeholder: 'Gruppenname',
      style: { width: '100%', minHeight: '42px', padding: '8px 12px', borderRadius: '10px', border: '1px solid rgba(128,128,128,.3)', background: 'var(--cd-tile-bg)', color: 'var(--primary-text-color, inherit)', font: 'inherit', boxSizing: 'border-box' },
      onInput: (e) => { groupName = e.target.value.trim(); },
    });

    const areaOptions = [
      { value: '', label: 'Ohne Raum', icon: 'mdi:home-outline' },
      ...this.areas.map((a) => ({ value: a.area_id, label: a.name, icon: this._getRoomIcon(a) })),
    ];
    const catOptions = DEVICE_CATEGORIES.map((c) => ({ value: c.id, label: c.name, icon: c.icon, color: c.color }));

    let selectedIcon = existingGroup?.icon || (selectedCat === 'leuchte' ? 'mdi:lightbulb-group' : 'mdi:power-plug');
    let isCustomIcon = !!existingGroup?.icon;
    const pinnedList = Array.isArray(this._dashboardConfig?.pinned_tiles) ? this._dashboardConfig.pinned_tiles : [];
    let isGroupPinned = !!(
      existingGroup?.pinned
      || existingGroup?.options?.pinned
      || (existingGroup?.id && (pinnedList.includes(`g:${existingGroup.id}`) || pinnedList.includes(`group:${existingGroup.id}`)))
    );

    const groupPinCard = h('div', {
      class: `feature-card${isGroupPinned ? ' active' : ''}`,
      style: { '--feat-color': 'var(--cd-accent, #29b6f6)', cursor: 'pointer' },
      ...(isGroupPinned ? { 'data-active': '' } : {}),
      onClick: () => {
        isGroupPinned = !isGroupPinned;
        groupPinCard.toggleAttribute('data-active', isGroupPinned);
        groupPinCard.classList.toggle('active', isGroupPinned);
      },
    },
    h('div', { class: 'feature-icon' }, icon('mdi:pin-outline')),
    h('div', { class: 'feature-info' },
      h('div', { class: 'feature-title' }, 'Anpinnen'),
      h('div', { class: 'feature-desc' }, 'Am Anfang der Kategorie anzeigen')),
    h('div', { class: 'switch-ui' }));

    const iconPicker = new IconPicker({
      hass: this.hass,
      value: selectedIcon,
      placeholder: 'Icon suchen',
      onChange: (v) => {
        selectedIcon = v;
        isCustomIcon = true;
      },
    });

    const areaDd = new CustomDropdown({
      options: areaOptions,
      value: selectedArea,
      placeholder: 'Raum',
      onChange: (v) => { selectedArea = v; },
    });

    const catDd = new CustomDropdown({
      options: catOptions,
      value: selectedCat,
      placeholder: 'Kategorie',
      onChange: (v) => {
        selectedCat = v;
        if (!isCustomIcon) {
          const catObj = DEVICE_CATEGORIES.find((c) => c.id === v);
          const defIcon = v === 'leuchte' ? 'mdi:lightbulb-group' : (catObj?.icon || 'mdi:power-plug');
          selectedIcon = defIcon;
          iconPicker._setValue(defIcon);
          isCustomIcon = false;
        }
      },
    });

    const getLabelForId = (id) => {
      if (this.groups[id]) return `${this.groups[id].name} (Gruppe)`;
      if (id.startsWith('d:')) {
        const parsed = parseChannelKey(id);
        const ent = this.entities.find((e) => e.entity_id === parsed.entityId);
        return ent?.name || ent?.original_name || parsed.entityId || id;
      }
      const dev = this.devices.find((d) => d.id === id);
      return dev?.name_by_user || dev?.name || id;
    };

    const countHeader = h('div', { class: 'field-label', style: { marginBottom: '6px' } }, `Elemente (${selectedIds.length})`);
    const tagsContainer = h('div', { style: { display: 'flex', flexWrap: 'wrap', gap: '6px' } });

    const renderTags = () => {
      const tags = selectedIds.map((id) => {
        const isG = !!this.groups[id];
        const label = getLabelForId(id);
        return h('span', { class: 'group-member-tag' },
          icon(isG ? 'mdi:folder-multiple' : 'mdi:lightbulb'),
          h('span', {}, label),
          h('button', {
            type: 'button',
            class: 'remove-btn',
            title: `${label} entfernen`,
            onClick: () => {
              selectedIds = selectedIds.filter((x) => x !== id);
              renderTags();
            },
          }, icon('mdi:close'))
        );
      });
      tagsContainer.replaceChildren(...tags);
      countHeader.textContent = `Elemente (${selectedIds.length})`;
    };
    renderTags();

    const availableToAdd = [];
    for (const [gid, g] of Object.entries(this.groups)) {
      if (existingGroup && gid === existingGroup.id) continue;
      if (!selectedIds.includes(gid)) {
        availableToAdd.push({ value: gid, label: `${g.name} (Gruppe)`, icon: 'mdi:folder-multiple' });
      }
    }
    for (const d of this.devices) {
      if (this.hiddenHybridDeviceIds?.has(d.id)) continue;
      const devEnts = (this.entities || []).filter((e) => e.device_id === d.id);
      if (isOwnIntegrationDevice(d, devEnts) && !isHybridMasterDevice(d)) continue;
      if (!selectedIds.includes(d.id)) {
        const dName = d.name_by_user || d.name || d.id;
        availableToAdd.push({ value: d.id, label: dName, icon: 'mdi:devices' });
      }
    }

    let addDropdownWrap = null;
    let addDd = null;
    if (availableToAdd.length > 0) {
      addDd = new CustomDropdown({
        options: availableToAdd,
        value: '',
        placeholder: '+ Element hinzufügen',
        onChange: (val) => {
          if (val && !selectedIds.includes(val)) {
            selectedIds.push(val);
            renderTags();
            addDd.setValue('');
          }
        },
      });
      addDropdownWrap = h('div', { style: { marginTop: '6px' } }, addDd.el);
    }

    const destroyPickers = () => {
      areaDd.destroy();
      catDd.destroy();
      addDd?.destroy();
      iconPicker.destroy();
    };

    const closeGroupModal = () => {
      overlay.remove();
      destroyPickers();
      if (isDirect) this._closeWizard();
    };
    if (isDirect) {
      overlay.style.background = 'transparent';
      overlay.style.backdropFilter = 'none';
      overlay.style.webkitBackdropFilter = 'none';
    }
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) closeGroupModal();
    });

    const dialog = h('div', { class: 'dialog group-modal-dialog' },
      h('div', { class: 'dialog-head' },
        icon(isMultiGroup ? 'mdi:folder-multiple' : 'mdi:lightbulb-group'),
        h('h2', {}, existingGroup ? 'Gruppe bearbeiten' : (isMultiGroup ? 'Hauptgruppe' : 'Neue Gruppe')),
        h('button', { class: 'icon-btn', 'aria-label': 'Schließen', onClick: closeGroupModal }, icon('mdi:close'))),
      h('div', { class: 'dialog-body', style: { display: 'flex', flexDirection: 'column', gap: '12px' } },
        h('div', { class: 'field' }, 'Gruppenname', nameInput),
        h('div', { class: 'field' }, 'Raum', areaDd.el),
        h('div', { class: 'field' }, 'Kategorie', catDd.el),
        h('div', { class: 'field' }, 'Icon', iconPicker.el),
        groupPinCard,
        h('div', {},
          countHeader,
          tagsContainer,
          addDropdownWrap)),
      h('div', { class: 'dialog-foot' },
        h('div', { class: 'dialog-foot-actions' },
          h('button', { class: 'btn', onClick: closeGroupModal }, 'Abbrechen'),
          existingGroup ? h('button', {
            class: 'btn danger',
            type: 'button',
            onClick: async () => {
              const removed = await this._removeGroup(existingGroup.id, existingGroup.name, true);
              if (removed) {
                overlay.remove();
                destroyPickers();
                if (isDirect) this.onSaved?.(null);
                else this._load();
              }
            },
          }, icon('mdi:delete-outline'), 'Auflösen') : null),
        h('div', { class: 'dialog-foot-actions' },
          h('button', {
            class: 'btn primary',
            onClick: async () => {
              if (!groupName) { showToast(this.el, 'Name fehlt', { error: true }); return; }
              if (selectedIds.length === 0) { showToast(this.el, 'Mind. 1 Element wählen', { error: true }); return; }
              try {
                const saveRes = await this.hass.callWS({
                  type: 'smarthome_companion/groups/save',
                  group: {
                    ...(existingGroup ? { id: existingGroup.id } : {}),
                    name: groupName,
                    area_id: selectedArea,
                    category: selectedCat,
                    icon: selectedIcon || (selectedCat === 'leuchte' ? 'mdi:lightbulb-group' : 'mdi:power-plug'),
                    pinned: !!isGroupPinned,
                    children: selectedIds,
                  },
                });
                const savedGid = saveRes?.group_id || saveRes?.group?.id || existingGroup?.id;
                if (savedGid) {
                  const gPinKey = `g:${savedGid}`;
                  try {
                    await this.hass.callWS({
                      type: 'smarthome_companion/dashboard/tile_order',
                      area_id: selectedArea || '__none__',
                      pin_key: gPinKey,
                      pinned: !!isGroupPinned,
                    });
                    const curPins = Array.isArray(this._dashboardConfig?.pinned_tiles) ? [...this._dashboardConfig.pinned_tiles] : [];
                    const cleanedPins = curPins.filter((k) => k !== gPinKey && k !== `group:${savedGid}`);
                    if (isGroupPinned) cleanedPins.push(gPinKey);
                    this._dashboardConfig = { ...(this._dashboardConfig || {}), pinned_tiles: cleanedPins };
                  } catch (_) { /* non-fatal */ }
                }
                overlay.remove();
                destroyPickers();
                this.selectedDevices.clear();
                if (isDirect) this.onSaved?.(null);
                else this._load();
              } catch (err) {
                showToast(this.el, `Fehler: ${err.message || err}`, { error: true });
              }
            },
          }, icon('mdi:check'), 'Speichern')))
    );

    overlay.appendChild(dialog);
    this.el.appendChild(overlay);
  }

  async _removeGroup(groupId, groupName, skipReload = false) {
    const conf = await showConfirmDialog(this.el, {
      title: 'Gruppe auflösen',
      message: `Gruppe „${groupName}“ auflösen? Geräte bleiben erhalten.`,
      confirmLabel: 'Auflösen',
      cancelLabel: 'Abbrechen',
      danger: true,
    });
    if (!conf) return false;
    try {
      await this.hass.callWS({ type: 'smarthome_companion/groups/delete', group_id: groupId });
      delete this.groups[groupId];
      this.selectedDevices.delete(groupId);
      if (!skipReload) {
        this._load();
      }
      return true;
    } catch (err) {
      showToast(this.el, `Fehler: ${err.message || err}`, { error: true });
      return false;
    }
  }

  _getHybridForDevice(d) {
    if (!d) return null;
    const cfg = this.configuredDevices?.[d.id];
    const hid = cfg?.hybrid_id;
    if (hid && this.hybrids?.[hid]) return this.hybrids[hid];
    for (const hCfg of Object.values(this.hybrids || {})) {
      if (hCfg && hCfg.master_device_id === d.id) return hCfg;
    }
    return null;
  }

  async _unpairHybrid(hCfg, onAfter = null) {
    if (!hCfg) return false;
    const conf = await showConfirmDialog(this.el, {
      title: 'Hybrid-Verknüpfung trennen?',
      message: `„${hCfg.name || 'Hybrid'}“ trennen?\n• Bevorzugtes Gerät übernimmt ursprüngliche Basis-ID\n• Bestehende Automationen bleiben erhalten`,
      confirmLabel: 'Trennen',
      cancelLabel: 'Abbrechen',
      danger: true,
    });
    if (!conf) return false;
    try {
      await this.hass.callWS({ type: 'smarthome_companion/hybrids/unpair', hybrid_id: hCfg.id });
      showToast(this.el, 'Hybrid-Verknüpfung getrennt');
      if (onAfter) onAfter();
      else if (this.directMode) {
        this._closeWizard();
        this.onSaved?.(null);
      } else {
        this.selectedDevice = null;
        this.step = 0;
        await this._load({ preserveStep0: true });
      }
      return true;
    } catch (err) {
      showToast(this.el, `Fehler: ${err.message || err}`, { error: true });
      return false;
    }
  }

  _openHybridModal({ proposal = null, deviceIds = null, baseDevice = null, baseConfig = null } = {}) {
    const mapProto = (p) => (p === 'zigbee' ? 'zigbee' : p === 'matter' ? 'matter' : 'wlan');
    const protoLabel = (p) => (p === 'zigbee' ? 'Zigbee' : p === 'matter' ? 'Matter' : 'WLAN');

    const transports = {}; // proto -> device_id
    let adoptedDeviceId = null;
    let adoptedProto = null;

    if (proposal) {
      for (const devInfo of (proposal.devices || [])) {
        const pr = mapProto(devInfo.protocol);
        transports[pr] = devInfo.device_id;
      }
      adoptedDeviceId = proposal.adopted_device_id || null;
      adoptedProto = proposal.adopted_protocol ? mapProto(proposal.adopted_protocol) : null;
    } else if (baseDevice) {
      const pr = mapProto(this._getDeviceProtocol(baseDevice));
      transports[pr] = baseDevice.id;
      adoptedDeviceId = baseDevice.id;
      adoptedProto = pr;
    } else if (Array.isArray(deviceIds)) {
      for (const id of deviceIds) {
        const dev = this._deviceMap?.get(id);
        if (!dev) continue;
        const pr = mapProto(this._getDeviceProtocol(dev));
        if (!transports[pr]) transports[pr] = id;
        if (this.configuredDevices?.[id] && !adoptedDeviceId) {
          adoptedDeviceId = id;
          adoptedProto = pr;
        }
      }
    }

    const seedDevs = Object.values(transports).map((id) => this._deviceMap?.get(id)).filter(Boolean);
    const firstDev = baseDevice || seedDevs[0];
    let hybName = proposal?.suggested_name || baseConfig?.custom_name || this._stripRoomName(firstDev?.name_by_user || firstDev?.name || 'Hybrid-Gerät', baseDevice?.area_id || proposal?.suggested_area_id) || 'Hybrid-Gerät';
    let hybArea = proposal?.suggested_area_id || baseDevice?.area_id || '';
    let hybCat = proposal?.suggested_category || baseConfig?.category || 'schalter';
    let hybIcon = baseConfig?.icon || '';
    let hybPrefProto = '';

    const overlay = h('div', { class: 'overlay', style: { zIndex: '1200' } });
    const nameInput = h('input', {
      type: 'text',
      value: hybName,
      placeholder: 'Gerätename (ohne Zigbee/WLAN)',
      onInput: (e) => { hybName = e.target.value.trim(); },
    });

    const areaOptions = [
      { value: '', label: 'Kein Raum', icon: 'mdi:map-marker-off' },
      ...this.areas.map((a) => ({ value: a.area_id, label: a.name, icon: this._getRoomIcon(a) })),
    ];
    const areaDd = new CustomDropdown({
      options: areaOptions,
      value: hybArea,
      placeholder: 'Raum wählen',
      onChange: (val) => { hybArea = val; },
    });

    const catOptions = DEVICE_CATEGORIES.map((c) => ({ value: c.id, label: c.name, icon: c.icon }));
    const catDd = new CustomDropdown({
      options: catOptions,
      value: hybCat,
      placeholder: 'Kategorie',
      onChange: (val) => { hybCat = val; },
    });

    const globalPref = this.hybridSettings?.preferred_protocol || 'zigbee';
    const prefDd = new CustomDropdown({
      options: [
        { value: '', label: `Globaler Standard (${protoLabel(globalPref)})`, icon: 'mdi:earth' },
        { value: 'zigbee', label: 'Zigbee bevorzugen', icon: 'mdi:zigbee' },
        { value: 'matter', label: 'Matter bevorzugen', icon: 'mdi:hub' },
        { value: 'wlan', label: 'WLAN bevorzugen', icon: 'mdi:wifi' },
      ],
      value: hybPrefProto,
      placeholder: 'Funkweg-Priorität',
      onChange: (val) => { hybPrefProto = val; },
    });

    const allPickableDevs = this._getSelectableCandidates()
      .filter((d) => !d.isVirtualEntity && !isHybridMasterDevice(d) && !this.groups[d.id]);

    const transportDropdowns = [];
    const buildTransportSelect = (proto) => {
      const opts = [
        { value: '', label: 'Nicht belegt', icon: 'mdi:close-circle-outline' },
        ...allPickableDevs.map((d) => {
          const dp = mapProto(this._getDeviceProtocol(d));
          const dName = d.name_by_user || d.name || d.id;
          return {
            value: d.id,
            label: `${dName} (${protoLabel(dp)})`,
            icon: dp === 'zigbee' ? 'mdi:zigbee' : (dp === 'matter' ? 'mdi:hub' : 'mdi:wifi'),
          };
        }),
      ];
      const dd = new CustomDropdown({
        options: opts,
        value: transports[proto] || '',
        placeholder: `${protoLabel(proto)}-Gerät wählen`,
        onChange: (val) => {
          if (val) transports[proto] = val;
          else delete transports[proto];
        },
      });
      transportDropdowns.push(dd);
      return h('div', { class: 'field' }, `${protoLabel(proto)}-Gerät`, dd.el);
    };

    const transportFields = [
      buildTransportSelect('zigbee'),
      buildTransportSelect('wlan'),
      buildTransportSelect('matter'),
    ];

    const destroyModal = () => {
      areaDd.destroy();
      catDd.destroy();
      prefDd.destroy();
      transportDropdowns.forEach((d) => d.destroy());
      overlay.remove();
    };
    overlay.addEventListener('click', (e) => { if (e.target === overlay) destroyModal(); });

    const saveBtn = h('button', {
      type: 'button',
      class: 'btn primary',
      onClick: async () => {
        const cleanEntries = Object.entries(transports).filter(([, v]) => !!v);
        if (cleanEntries.length < 2) {
          showToast(this.el, 'Mindestens 2 verschiedene Funkwege wählen', { error: true });
          return;
        }
        const usedIds = cleanEntries.map(([, v]) => v);
        if (new Set(usedIds).size !== usedIds.length) {
          showToast(this.el, 'Jeder Funkweg benötigt ein eigenes Gerät', { error: true });
          return;
        }
        if (!hybName) {
          showToast(this.el, 'Name fehlt', { error: true });
          return;
        }
        saveBtn.disabled = true;
        try {
          await this.hass.callWS({
            type: 'smarthome_companion/hybrids/save',
            name: hybName,
            area_id: hybArea || '',
            category: hybCat,
            icon: hybIcon || undefined,
            preferred_protocol: hybPrefProto || null,
            transports: Object.fromEntries(cleanEntries),
            adopted_device_id: adoptedDeviceId,
            adopted_protocol: adoptedProto,
          });
          destroyModal();
          this.selectedDevices.clear();
          showToast(this.el, `Hybrid „${hybName}“ eingerichtet`);
          if (this.directMode) {
            this._closeWizard();
            this.onSaved?.(null);
          } else {
            this.selectedDevice = null;
            this.step = 0;
            await this._load({ preserveStep0: true });
            this.onSaved?.(null);
          }
        } catch (err) {
          saveBtn.disabled = false;
          showToast(this.el, `Fehler: ${err.message || err}`, { error: true });
        }
      },
    }, icon('mdi:check'), 'Hybrid speichern');

    const dialog = h('div', { class: 'dialog group-modal-dialog' },
      h('div', { class: 'dialog-head' },
        icon('mdi:swap-horizontal-bold'),
        h('h2', {}, baseDevice ? 'Als Hybrid erweitern' : 'Hybrid-Gerät verbinden'),
        h('button', { class: 'icon-btn', 'aria-label': 'Schließen', onClick: destroyModal }, icon('mdi:close'))),
      h('div', { class: 'dialog-body', style: { display: 'flex', flexDirection: 'column', gap: '12px' } },
        h('div', { class: 'hint' }, '• Master erhält sauberen Basis-Namen & entity_id\n• Einzelgeräte bekommen _zigbee / _wlan / _matter\n• Bestehende Automationen bleiben unterbrechungsfrei erhalten'),
        h('div', { class: 'field' }, 'Master-Name', nameInput),
        h('div', { class: 'field' }, 'Raum', areaDd.el),
        h('div', { class: 'field' }, 'Kategorie', catDd.el),
        ...transportFields,
        h('details', { class: 'adv-options' },
          h('summary', {}, icon('mdi:tune'), 'Erweiterte Funkweg-Priorität'),
          h('div', { class: 'adv-content' },
            h('div', { class: 'field' }, 'Bevorzugter Funkweg (Gerät)', prefDd.el)))),
      h('div', { class: 'dialog-foot' },
        h('div', { class: 'dialog-foot-actions' },
          h('button', { type: 'button', class: 'btn', onClick: destroyModal }, 'Abbrechen')),
        h('div', { class: 'dialog-foot-actions' }, saveBtn)));

    overlay.appendChild(dialog);
    this.el.appendChild(overlay);
  }

  // ═══════════════ Strip Room Name Helper ═══════════════
  _stripRoomName(rawName, preferredAreaId) {
    if (!rawName) return '';
    let name = rawName;

    const candidateAreas = [];
    if (preferredAreaId) {
      const a = this.areas.find((ar) => ar.area_id === preferredAreaId);
      if (a) candidateAreas.push(a);
    }
    for (const a of this.areas) {
      if (!candidateAreas.includes(a)) candidateAreas.push(a);
    }

    for (const a of candidateAreas) {
      if (!a?.name) continue;
      const aName = a.name.trim();
      if (!aName || aName.length < 2) continue;

      const escaped = aName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const prefixRegex = new RegExp(`^${escaped}\\s*[-_–—:]*\\s*`, 'i');
      const compoundPrefixRegex = new RegExp(`^${escaped}(?=[A-ZÄÖÜa-zäöü])`, 'i');
      const suffixRegex = new RegExp(`\\s*[-_–—:]*\\s*${escaped}$`, 'i');
      const midRegex = new RegExp(`\\s+[-_–—:]*\\s*${escaped}\\s*[-_–—:]*\\s+`, 'i');
      const wordRegex = new RegExp(`\\b${escaped}\\b`, 'i');

      let stripped = name;
      if (prefixRegex.test(stripped)) {
        stripped = stripped.replace(prefixRegex, '');
      } else if (compoundPrefixRegex.test(stripped)) {
        stripped = stripped.replace(compoundPrefixRegex, '');
      } else if (suffixRegex.test(stripped)) {
        stripped = stripped.replace(suffixRegex, '');
      } else if (midRegex.test(stripped)) {
        stripped = stripped.replace(midRegex, ' ');
      } else if (wordRegex.test(stripped)) {
        stripped = stripped.replace(wordRegex, '');
      }

      stripped = stripped.trim().replace(/\s{2,}/g, ' ').replace(/^[-_–—:\s]+|[-_–—:\s]+$/g, '');
      if (stripped.length > 0 && stripped.length < name.length) {
        name = stripped;
        if (!this.selectedAreaId) {
          this.selectedAreaId = a.area_id;
        }
        break;
      }
    }

    if (name) name = name.charAt(0).toUpperCase() + name.slice(1);
    return name;
  }

  _isSmokeEntity(entity) {
    if (!entity || domainOf(entity.entity_id) !== 'binary_sensor') return false;
    const st = this.hass?.states?.[entity.entity_id];
    const dc = st?.attributes?.device_class || entity.device_class || entity.original_device_class || '';
    if (dc === 'smoke') return true;
    const hay = `${entity.entity_id} ${entity.name || ''} ${entity.original_name || ''}`.toLowerCase();
    return /(?:smoke|rauch)/.test(hay);
  }

  _inferChannelCategory(entity, device, fallbackCat = 'schalter') {
    const id = (entity?.entity_id || '').toLowerCase();
    const name = `${entity?.name || ''} ${entity?.original_name || ''}`.toLowerCase();
    const hay = `${id} ${name}`;
    if (/(?:wasserventil|ventil|valve|bewaesser|bewässer|irrigation|sprinkler|beregn)/.test(hay)) return 'wasserventil';
    if (/(?:pumpe|pump)/.test(hay)) return 'pumpe';
    if (/(?:steckdose|plug|outlet)/.test(hay)) return 'steckdose';
    if (/(?:jalousie|rolllad|shutter|blind|markise)/.test(hay)) return 'jalousie';
    const dom = domainOf(entity?.entity_id || '');
    if (dom === 'cover') return 'jalousie';
    if (dom === 'valve') return 'wasserventil';
    if (dom === 'climate') return 'klima';
    if (dom === 'media_player') return 'fernseher';
    if (dom === 'light' && fallbackCat !== 'wasserventil' && fallbackCat !== 'pumpe') return 'leuchte';
    return fallbackCat || 'schalter';
  }

  _detectSensorType(entity, devName = '') {
    if (!entity || isOwnIntegrationEntity(entity) || entity.entity_category === 'diagnostic' || entity.entity_category === 'config') {
      return 'ignore';
    }
    const st = this.hass?.states?.[entity.entity_id];
    const dc = st?.attributes?.device_class || entity.device_class || entity.original_device_class || '';
    const unit = st?.attributes?.unit_of_measurement || '';
    const dom = domainOf(entity.entity_id);
    const hay = `${entity.entity_id} ${entity.name || ''} ${entity.original_name || ''} ${devName}`.toLowerCase();
    if (dom === 'sensor') {
      if (dc === 'temperature' || unit === '°C' || unit === '°F') return 'temperature';
      if (dc === 'moisture') return 'moisture';
      if (dc === 'humidity' || unit === '%') {
        if (/(?:boden|soil|plant|pflanze|garten|blume|beet|moisture|feucht)/.test(hay)) return 'moisture';
        if (dc === 'humidity') return 'humidity';
      }
      return 'ignore';
    }
    if (dom === 'binary_sensor') {
      if (['motion', 'occupancy', 'presence'].includes(dc)) return 'motion';
      if (dc === 'moisture') return 'moisture';
      return 'ignore';
    }
    return 'ignore';
  }

  _isNewRoomForDevice(areaId) {
    if (!areaId) return false;
    const room = (this._dashboardRooms || []).find((r) => r.area_id === areaId);
    if (!room) return true;
    const hasTiles = Array.isArray(room.tiles) && room.tiles.length > 0;
    const hasSensors = room.all_sensors && Object.values(room.all_sensors).some((arr) => Array.isArray(arr) && arr.length > 0);
    return !hasTiles && !hasSensors;
  }

  _getRoomIcon(areaOrId) {
    if (!areaOrId) return 'mdi:home-outline';
    const areaId = typeof areaOrId === 'string' ? areaOrId : areaOrId.area_id;
    const areaObj = typeof areaOrId === 'object' ? areaOrId : this.areas?.find((a) => a.area_id === areaId);
    const cfgIcon = areaId ? this._dashboardConfig?.rooms?.[areaId]?.icon : '';
    const dashIcon = areaId ? this._dashboardRooms?.find((r) => r.area_id === areaId)?.icon : '';
    return cfgIcon || dashIcon || areaObj?.icon || 'mdi:home-outline';
  }

  _extractChannelMatchTokens(channelEntity) {
    if (!channelEntity) return [];
    const tokens = [];
    const eid = (channelEntity.entity_id || '').toLowerCase();
    const numMatches = eid.match(/(?:_|ch|channel|l|switch|light|plug|outlet|socket)(\d+)(?:$|_)/g) || [];
    for (const m of numMatches) {
      const digits = m.match(/\d+/);
      if (digits) tokens.push(digits[0]);
    }
    const rawName = (channelEntity.name || channelEntity.original_name || '').toLowerCase();
    for (const part of rawName.split(/[^a-z0-9äöüß]+/)) {
      if (part.length >= 2) tokens.push(part);
    }
    return [...new Set(tokens)];
  }

  _sensorChannelMatchScore(sensor, channelEntity) {
    if (!channelEntity) return 0;
    const tokens = this._extractChannelMatchTokens(channelEntity);
    if (!tokens.length) return 0;
    const hay = `${sensor.entity_id || ''} ${sensor.name || ''} ${sensor.original_name || ''}`.toLowerCase();
    let hits = 0;
    for (const t of tokens) {
      if (/^\d+$/.test(t)) {
        const re = new RegExp(`(?:_|ch|channel|l|switch|outlet|socket)${t}(?:$|_|\\b)`);
        if (re.test(hay)) hits += 2;
      } else if (hay.includes(t)) {
        hits += 1;
      }
    }
    return hits;
  }

  _detectPowerSensor(sensors, channelEntity = null, excludeIds = null) {
    const candidates = [];
    for (const s of sensors) {
      if (!s || s.entity_category === 'config' || excludeIds?.has(s.entity_id)) continue;
      const st = this.hass?.states?.[s.entity_id];
      const dc = (st?.attributes?.device_class || s.device_class || s.original_device_class || '').toLowerCase();
      const unit = (st?.attributes?.unit_of_measurement || s.unit_of_measurement || '').trim().toLowerCase();
      const nameStr = `${s.entity_id} ${s.original_name || ''} ${s.name || ''} ${st?.attributes?.friendly_name || ''}`.toLowerCase();
      if (dc && !['power', 'apparent_power', 'reactive_power'].includes(dc)) continue;
      if (unit && !['w', 'kw', 'mw'].includes(unit)) continue;
      const isPower = dc === 'power'
        || ['w', 'kw', 'mw'].includes(unit)
        || (nameStr.includes('power') && !nameStr.includes('power_factor') && !nameStr.includes('energy'))
        || nameStr.includes('leistung');
      if (!isPower) continue;
      let score = 0;
      if (dc === 'power') score += 100;
      if (['w', 'kw', 'mw'].includes(unit)) score += 60;
      if (s.entity_category === 'diagnostic') score -= 15;
      score += this._sensorChannelMatchScore(s, channelEntity) * 35;
      candidates.push({ entity_id: s.entity_id, score });
    }
    candidates.sort((a, b) => b.score - a.score);
    return candidates[0]?.entity_id || '';
  }

  _detectEnergySensor(sensors, channelEntity = null, excludeIds = null) {
    const NON_ENERGY_CLASSES = new Set([
      'power', 'apparent_power', 'reactive_power', 'water', 'gas', 'volume',
      'monetary', 'duration', 'voltage', 'current', 'frequency', 'power_factor',
      'temperature', 'humidity', 'battery', 'illuminance', 'pressure', 'signal_strength',
      'data_size', 'data_rate', 'timestamp', 'enum',
    ]);
    const ENERGY_UNITS = new Set(['kwh', 'wh', 'mwh']);
    const NON_ENERGY_UNITS = new Set(['w', 'kw', 'mw', 'va', 'var', 'v', 'a', 'ma', 'hz', 'l', 'm³', 'm3', 'eur', 'usd', 's', 'min', 'h', '°c', '°f', '%']);
    const candidates = [];
    for (const s of sensors) {
      if (!s || s.entity_category === 'config' || excludeIds?.has(s.entity_id)) continue;
      const st = this.hass?.states?.[s.entity_id];
      const dc = (st?.attributes?.device_class || s.device_class || s.original_device_class || '').toLowerCase();
      const sc = (st?.attributes?.state_class || s.capabilities?.state_class || '').toLowerCase();
      const unit = (st?.attributes?.unit_of_measurement || s.unit_of_measurement || '').trim().toLowerCase();
      const nameStr = `${s.entity_id} ${s.original_name || ''} ${s.name || ''} ${st?.attributes?.friendly_name || ''}`.toLowerCase();

      if (dc && dc !== 'energy' && NON_ENERGY_CLASSES.has(dc)) continue;
      if (unit && !ENERGY_UNITS.has(unit) && NON_ENERGY_UNITS.has(unit)) continue;

      const hasEnergyUnit = ENERGY_UNITS.has(unit);
      const hasTotalStateClass = sc === 'total' || sc === 'total_increasing';
      const hasEnergyKeyword = /(energy|energie|verbrauch|consumption|summation|kwh|mwh|\bwh\b)/.test(nameStr);
      const matches = dc === 'energy'
        || hasEnergyUnit
        || (hasTotalStateClass && !dc && !unit && hasEnergyKeyword)
        || (!dc && !unit && hasEnergyKeyword);
      if (!matches) continue;

      let score = 0;
      if (dc === 'energy') score += 100;
      if (hasEnergyUnit) score += 60;
      if (hasTotalStateClass) score += 40;
      if (hasEnergyKeyword) score += 20;
      if (/(today|daily|yesterday|month|monthly|week|weekly|year|annual|hour|hourly|returned|export|feed_in|tages|heute|gestern|woche|monat|jahr|einspeisung|rueckspeisung|rückspeisung)/.test(nameStr)) {
        score -= 25;
      }
      if (s.entity_category === 'diagnostic') score -= 15;
      const chScore = this._sensorChannelMatchScore(s, channelEntity);
      score += chScore * 35;
      candidates.push({ entity_id: s.entity_id, score, chScore });
    }
    candidates.sort((a, b) => b.score - a.score);
    return candidates[0] || null;
  }

  // ═══════════════ Initialize selected device ═══════════════
  _initDevice() {
    const d = this.selectedDevice;
    if (!d) return;
    const existing = this._getConfiguredConfigForCandidate(d);

    this.selectedAreaId = d.area_id || '';
    this.roomIcon = this._isNewRoomForDevice(this.selectedAreaId) ? this._getRoomIcon(this.selectedAreaId) : '';
    this.customIcon = existing?.icon || '';
    this.forceOwnRow = !!existing?.options?.force_own_row;
    const pinnedList = this._dashboardConfig?.pinned_tiles || [];
    const devTileKey = d.isVirtualEntity ? d.id : `dev:${d.id}`;
    this.pinned = pinnedList.includes(devTileKey) || pinnedList.some((k) => String(k).startsWith(`d:${d.id}:`)) || !!existing?.options?.pinned;
    this.displayMode = existing?.options?.display_mode || 'individual';
    let rawName = existing?.custom_name || d.name_by_user || d.name || '';
    if (!existing?.custom_name) {
      rawName = this._stripRoomName(rawName, this.selectedAreaId);
    }
    this.customName = rawName;

    // Related entities (strictly exclude non-hybrid internal, config & diagnostic entities)
    const isHybrid = isHybridMasterDevice(d);
    this._activeHybridCfg = this._getHybridForDevice(d);
    this._hybridPreferredProtocol = this._activeHybridCfg?.preferred_protocol || '';
    const devEntities = (
      d.isVirtualEntity
        ? this.entities.filter((e) => e.entity_id === d.entity_id)
        : this.entities.filter((e) => e.device_id === d.id)
    ).filter(
      (e) => !e.disabled_by
        && (isHybrid || !isOwnIntegrationEntity(e))
        && e.entity_category !== 'config'
        && e.entity_category !== 'diagnostic',
    );
    let controllable = devEntities.filter((e) => isControllableActuator(e));
    const reenableIds = new Set();
    if (!controllable.length && !d.isVirtualEntity) {
      const disabledActs = this.entities.filter(
        (e) => e.device_id === d.id
          && e.disabled_by === 'user'
          && !isOwnIntegrationEntity(e)
          && e.entity_category !== 'config'
          && e.entity_category !== 'diagnostic'
          && isControllableActuator(e, { allowDisabledUser: true }),
      );
      if (disabledActs.length) {
        controllable = disabledActs;
        disabledActs.forEach((e) => reenableIds.add(e.entity_id));
      }
    }
    const sensors = devEntities.filter((e) => domainOf(e.entity_id) === 'sensor');
    const smokeEntities = devEntities.filter((e) => this._isSmokeEntity(e));
    const devLabel = `${d.name_by_user || d.name || ''} ${d.model || ''}`;

    const existingSensors = existing?.entities?.room_sensors || {};
    const rawRoomSensors = devEntities.filter(
      (e) => ['sensor', 'binary_sensor'].includes(domainOf(e.entity_id)) && !this._isSmokeEntity(e),
    );
    this.sensorEntities = rawRoomSensors.map((e) => {
      const saved = existingSensors[e.entity_id] || (e.unique_id
        ? Object.values(existingSensors).find((s) => s?.unique_id === e.unique_id)
        : null);
      const detectedType = this._detectSensorType(e, devLabel);
      const type = saved?.type || (saved?.enabled === false ? 'ignore' : detectedType);
      return {
        entity_id: e.entity_id,
        unique_id: e.unique_id || '',
        name: e.name || e.original_name || this.hass?.states?.[e.entity_id]?.attributes?.friendly_name || e.entity_id,
        detectedType,
        type,
        placement: (saved?.placement === 'tile' || saved?.placement === 'room') ? saved.placement : null,
      };
    });

    // Auto-detect power & energy
    const powerSensor = this._detectPowerSensor(sensors);
    const energySensor = this._detectEnergySensor(sensors)?.entity_id || '';

    // Auto-detect category
    const devHay = `${d.name_by_user || d.name || ''} ${d.model || ''}`.toLowerCase();
    let autoCat = 'schalter';
    if (smokeEntities.length > 0 && !controllable.length) autoCat = 'rauchmelder';
    else if (controllable.some((e) => domainOf(e.entity_id) === 'alarm_control_panel')) autoCat = 'alarmanlage';
    else if (controllable.some((e) => domainOf(e.entity_id) === 'camera')) autoCat = 'kamera';
    else if (controllable.some((e) => domainOf(e.entity_id) === 'cover')) autoCat = 'jalousie';
    else if (/(?:wasserventil|ventil|valve|bewaesser|bewässer|irrigation|sprinkler)/.test(devHay) || controllable.some((e) => domainOf(e.entity_id) === 'valve')) autoCat = 'wasserventil';
    else if (/(?:pumpe|pump)/.test(devHay)) autoCat = 'pumpe';
    else if (controllable.some((e) => domainOf(e.entity_id) === 'light')) autoCat = 'leuchte';
    else if (controllable.some((e) => domainOf(e.entity_id) === 'climate')) autoCat = 'klima';
    else if (controllable.some((e) => domainOf(e.entity_id) === 'media_player')) autoCat = 'fernseher';
    else if (/(?:steckdose|plug)/.test(devHay)) autoCat = 'steckdose';
    else if (!controllable.length && (this.sensorEntities.some((s) => s.detectedType === 'moisture') || /(?:boden|soil|plant|pflanze|blume|beet)/.test(devHay))) autoCat = 'bodenmessgeraet';
    else if (!controllable.length && this.sensorEntities.some((s) => s.detectedType === 'motion')) autoCat = 'bewegungsmelder';
    else if (!controllable.length && this.sensorEntities.some((s) => s.detectedType === 'temperature' || s.detectedType === 'humidity')) autoCat = 'raummessgeraet';

    this.selectedCategory = existing?.category || autoCat;
    const defaultPlacement = ['bodenmessgeraet', 'rauchmelder'].includes(this.selectedCategory) ? 'tile' : 'room';
    this.sensorPlacement = existing?.options?.sensor_placement || defaultPlacement;

    // Sub-entities / channels
    const existingSubs = existing?.entities?.sub_entities || {};
    const assignedEnergy = new Set();
    const assignedPower = new Set();
    this.channels = controllable.map((e, idx) => {
      const sub = existingSubs[e.entity_id] || (e.unique_id
        ? Object.values(existingSubs).find((s) => s?.unique_id === e.unique_id)
        : null) || {};
      let channelName = sub.custom_name || sub.name || e.name || e.original_name || (controllable.length > 1 ? `Kanal ${idx + 1}` : this.customName);
      if (!sub.custom_name && !sub.name) {
        channelName = this._stripRoomName(channelName, this.selectedAreaId);
      }
      let chPower = sub.power || '';
      let autoChPower = '';
      if (!chPower) {
        if (controllable.length > 1) {
          const matchedPower = this._detectPowerSensor(sensors, e, assignedPower);
          chPower = matchedPower || (idx === 0 ? (existing?.entities?.power || powerSensor) : '');
          if (chPower) assignedPower.add(chPower);
          autoChPower = chPower;
        } else {
          chPower = existing?.entities?.power || powerSensor;
          autoChPower = powerSensor;
        }
      }
      let chEnergy = sub.energy || '';
      let autoChEnergy = '';
      if (!chEnergy) {
        if (controllable.length > 1) {
          const match = this._detectEnergySensor(sensors, e, assignedEnergy);
          if (match && (match.chScore > 0 || idx === 0)) {
            chEnergy = match.entity_id;
          } else if (idx === 0) {
            chEnergy = existing?.entities?.energy || energySensor;
          }
          if (chEnergy) assignedEnergy.add(chEnergy);
          autoChEnergy = chEnergy;
        } else {
          chEnergy = existing?.entities?.energy || energySensor;
          autoChEnergy = energySensor;
        }
      }
      return {
        entity_id: e.entity_id,
        unique_id: e.unique_id || '',
        enabled: sub.enabled !== undefined ? !!sub.enabled : true,
        wasPending: !!existing && (sub.enabled === false || (!existingSubs[e.entity_id] && controllable.length > 1 && Object.keys(existingSubs).length > 0 && !Object.values(existingSubs).some((s) => s?.unique_id && s.unique_id === e.unique_id))),
        name: channelName,
        area_id: sub.area_id || '',
        category: sub.category || this._inferChannelCategory(e, d, this.selectedCategory),
        power: chPower,
        energy: chEnergy,
        _autoPower: autoChPower,
        _autoEnergy: autoChEnergy,
        _wasDisabledByUser: reenableIds.has(e.entity_id),
        presence_simulation: !!(sub.presence_simulation || (idx === 0 && existing?.entities?.presence_simulation)),
        force_own_row: sub.force_own_row !== undefined ? !!sub.force_own_row : !!existing?.options?.force_own_row,
      };
    });

    this.smokeEntityId = smokeEntities[0]?.entity_id || devEntities.find((e) => domainOf(e.entity_id) === 'binary_sensor')?.entity_id || '';
    const savedPrimary = existing?.entities?.primary || '';
    const validSavedPrimary = savedPrimary && (
      controllable.some((e) => e.entity_id === savedPrimary)
      || (this.selectedCategory === 'rauchmelder' && savedPrimary === this.smokeEntityId)
    ) ? savedPrimary : '';
    this.primaryEntityId = validSavedPrimary
      || controllable[0]?.entity_id
      || (this.selectedCategory === 'rauchmelder' ? this.smokeEntityId : '')
      || '';
    this.powerEntityId = existing?.entities?.power || powerSensor;
    this.energyEntityId = existing?.entities?.energy || energySensor;
  }

  // ═══════════════ STEP 1: Details (Name, Kategorie, Raum) ═══════════════
  _renderStep1() {
    this._cleanupDropdowns();
    const areaOptions = [
      { value: '', label: 'Kein Raum', icon: 'mdi:map-marker-off' },
      ...this.areas.map((a) => ({ value: a.area_id, label: a.name, icon: this._getRoomIcon(a) })),
    ];

    const areaDropdown = new CustomDropdown({
      options: areaOptions,
      value: this.selectedAreaId,
      placeholder: 'Raum',
      onChange: (val) => {
        this.selectedAreaId = val;
        if (this._isNewRoomForDevice(val)) {
          this.roomIcon = this._getRoomIcon(val);
        } else {
          this.roomIcon = '';
        }
        if (this.customName) {
          const stripped = this._stripRoomName(this.customName, val);
          if (stripped && stripped !== this.customName) {
            this.customName = stripped;
          }
        }
        preserveScroll(this.body, () => this._renderStep1());
      },
    });
    this._dropdowns.push(areaDropdown);

    const isNewRoom = this._isNewRoomForDevice(this.selectedAreaId);
    let roomIconField = null;
    if (isNewRoom) {
      const roomIconPicker = new IconPicker({
        hass: this.hass,
        value: this.roomIcon || 'mdi:home-outline',
        priorityIcons: ROOM_ICON_OPTIONS,
        placeholder: 'Raum-Icon suchen',
        onChange: (val) => { this.roomIcon = val || 'mdi:home-outline'; },
      });
      this._dropdowns.push(roomIconPicker);
      roomIconField = h('div', { class: 'field' }, 'Raum-Icon', roomIconPicker.el);
    }

    const nameInput = h('input', {
      type: 'text', value: this.customName, placeholder: 'Gerätename',
      onInput: (e) => { this.customName = e.target.value; },
    });

    const curCat = DEVICE_CATEGORIES.find((c) => c.id === this.selectedCategory) || DEVICE_CATEGORIES[0];
    const heroIconEl = icon(this.customIcon || curCat.icon);
    const devIconPicker = new IconPicker({
      hass: this.hass,
      value: this.customIcon || curCat.icon,
      placeholder: 'Icon suchen',
      onChange: (val) => {
        this.customIcon = val;
        const activeCat = DEVICE_CATEGORIES.find((c) => c.id === this.selectedCategory) || DEVICE_CATEGORIES[0];
        heroIconEl.setAttribute('icon', val || activeCat.icon);
      },
    });
    this._dropdowns.push(devIconPicker);

    const catGrid = h('div', { class: 'cat-grid' },
      ...DEVICE_CATEGORIES.map((c) => {
        const card = h('div', {
          class: 'cat-card', style: { '--cat-color': c.color },
          ...(this.selectedCategory === c.id ? { 'data-selected': '' } : {}),
          onClick: () => {
            const prevCat = this.selectedCategory;
            this.selectedCategory = c.id;
            this.channels.forEach((ch) => {
              if (!ch.category || ch.category === prevCat) {
                ch.category = c.id;
              }
            });
            if (c.id === 'rauchmelder' && !this.primaryEntityId && this.smokeEntityId) {
              this.primaryEntityId = this.smokeEntityId;
            }
            if (!this.customIcon) {
              devIconPicker._setValue(c.icon);
            }
            preserveScroll(this.body, () => this._render());
          },
        },
        icon(c.icon),
        h('div', {}, c.name));
        return card;
      }));

    const hero = h('div', { class: 'win11-hero-badge', style: { color: curCat.color, '--hero-color': curCat.color } }, heroIconEl);

    const ownRowCard = h('div', {
      class: `feature-card${this.forceOwnRow ? ' active' : ''}`,
      style: { '--feat-color': 'var(--cd-accent, #29b6f6)', cursor: 'pointer', marginTop: '10px' },
      ...(this.forceOwnRow ? { 'data-active': '' } : {}),
      onClick: () => {
        this.forceOwnRow = !this.forceOwnRow;
        this.channels.forEach((ch) => { ch.force_own_row = this.forceOwnRow; });
        ownRowCard.toggleAttribute('data-active', this.forceOwnRow);
        ownRowCard.classList.toggle('active', this.forceOwnRow);
      },
    },
    h('div', { class: 'feature-icon' }, icon('mdi:view-agenda-outline')),
    h('div', { class: 'feature-info' },
      h('div', { class: 'feature-title' }, 'Eigene Zeile erzwingen'),
      h('div', { class: 'feature-desc' }, 'Nicht kompakt gruppieren · Volle Breite')),
    h('div', { class: 'switch-ui' }));

    const pinCard = h('div', {
      class: `feature-card${this.pinned ? ' active' : ''}`,
      style: { '--feat-color': 'var(--cd-accent, #29b6f6)', cursor: 'pointer', marginTop: '8px' },
      ...(this.pinned ? { 'data-active': '' } : {}),
      onClick: () => {
        this.pinned = !this.pinned;
        pinCard.toggleAttribute('data-active', this.pinned);
        pinCard.classList.toggle('active', this.pinned);
      },
    },
    h('div', { class: 'feature-icon' }, icon('mdi:pin-outline')),
    h('div', { class: 'feature-info' },
      h('div', { class: 'feature-title' }, 'Anpinnen'),
      h('div', { class: 'feature-desc' }, 'Am Anfang der Kategorie anzeigen')),
    h('div', { class: 'switch-ui' }));

    let soilPlacementBlock = null;
    if (['bodenmessgeraet', 'rauchmelder', 'raummessgeraet', 'bewegungsmelder'].includes(this.selectedCategory)) {
      const catMeta = DEVICE_CATEGORIES.find((c) => c.id === this.selectedCategory);
      const accent = catMeta?.color || 'var(--cd-accent)';
      const isSmoke = this.selectedCategory === 'rauchmelder';
      const mkPlaceOption = (val, ic, title, desc) => {
        const active = this.sensorPlacement === val;
        return h('div', {
          class: `cat-card${active ? ' active' : ''}`,
          style: { '--cat-color': accent, flex: '1 1 160px', minWidth: '0', textAlign: 'left', padding: '10px 12px', display: 'flex', alignItems: 'center', gap: '10px' },
          ...(active ? { 'data-selected': '' } : {}),
          onClick: () => {
            this.sensorPlacement = val;
            preserveScroll(this.body, () => this._renderStep1());
          },
        },
        icon(ic),
        h('div', { style: { minWidth: '0' } },
          h('div', { style: { fontWeight: '600', fontSize: '13px' } }, title),
          h('div', { class: 'hint', style: { fontSize: '11px' } }, desc)));
      };
      soilPlacementBlock = h('div', { style: { marginTop: '12px' } },
        h('div', { class: 'section-title' }, 'Anzeige im Raum'),
        h('div', { style: { display: 'flex', gap: '8px', flexWrap: 'wrap' } },
          mkPlaceOption('tile', catMeta?.icon || 'mdi:card-outline', 'Eigene Gerätekachel', isSmoke ? 'Als Kachel oben im Raum' : 'Als reguläre Kachel im Raum'),
          mkPlaceOption('room', 'mdi:dock-bottom', 'Raum-Statusleiste', isSmoke ? 'Unten in Raumkachel · Alarm färbt Raum rot' : 'Kompakt unten in der Raumkachel')));
    }

    this.body.replaceChildren(
      ...[
        hero,
        h('div', { class: 'section-title' }, 'Details'),
        h('div', { class: 'fields' },
          h('div', { class: 'field' }, 'Name', nameInput),
          h('div', { class: 'field' }, 'Raum', areaDropdown.el),
          roomIconField,
          h('div', { class: 'field' }, 'Icon', devIconPicker.el)),
        ownRowCard,
        pinCard,
        soilPlacementBlock,
        h('div', { class: 'section-title', style: { marginTop: '12px' } }, 'Kategorie'),
        catGrid,
      ].filter(Boolean));
  }

  _buildSensorSection() {
    if (!this.sensorEntities || !this.sensorEntities.length) return null;

    const isSoil = this.selectedCategory === 'bodenmessgeraet';
    const isSensorCat = ['bodenmessgeraet', 'raummessgeraet', 'bewegungsmelder'].includes(this.selectedCategory);
    const sensorCatMeta = DEVICE_CATEGORIES.find((c) => c.id === this.selectedCategory);
    let soilPlacementRow = null;
    if (isSensorCat) {
      const accent = sensorCatMeta?.color || '#4caf50';
      const mkSoilBtn = (val, ic, title, desc) => {
        const active = this.sensorPlacement === val;
        return h('div', {
          class: `cat-card${active ? ' active' : ''}`,
          style: { '--cat-color': accent, flex: '1 1 160px', minWidth: '0', textAlign: 'left', padding: '10px 12px', display: 'flex', alignItems: 'center', gap: '10px' },
          ...(active ? { 'data-selected': '' } : {}),
          onClick: () => {
            this.sensorPlacement = val;
            preserveScroll(this.body, () => this._renderStep2());
          },
        },
        icon(ic),
        h('div', { style: { minWidth: '0' } },
          h('div', { style: { fontWeight: '600', fontSize: '13px' } }, title),
          h('div', { class: 'hint', style: { fontSize: '11px' } }, desc)));
      };
      soilPlacementRow = h('div', { style: { marginBottom: '12px' } },
        h('div', { class: 'section-title' }, 'Platzierung'),
        h('div', { style: { display: 'flex', gap: '8px', flexWrap: 'wrap' } },
          mkSoilBtn('tile', sensorCatMeta?.icon || 'mdi:card-outline', 'Eigene Gerätekachel', 'Als reguläre Kachel im Raum'),
          mkSoilBtn('room', 'mdi:dock-bottom', 'Raum-Statusleiste', 'Kompakt unten in der Raumkachel')));
    }

    const cards = this.sensorEntities.map((s) => {
      const st = this.hass?.states?.[s.entity_id];
      const liveVal = st
        ? (st.attributes?.unit_of_measurement ? `${st.state} ${st.attributes.unit_of_measurement}` : st.state)
        : '—';

      if (isSoil) {
        const preferredType = s.detectedType !== 'ignore'
          ? s.detectedType
          : ((st?.attributes?.unit_of_measurement === '°C' || st?.attributes?.unit_of_measurement === '°F')
            ? 'temperature'
            : (st?.attributes?.unit_of_measurement === '%' ? 'moisture' : 'temperature'));
        const isChecked = s.type !== 'ignore';
        const toggleSoilChannel = () => {
          s.type = s.type === 'ignore' ? preferredType : 'ignore';
          preserveScroll(this.body, () => this._renderStep2());
        };
        const toggleUi = h('div', {
          class: 'switch-ui',
          ...(isChecked ? { 'data-active': '' } : {}),
        });
        const typeLabel = preferredType === 'moisture' ? 'Bodenfeuchtigkeit' : 'Bodentemperatur';
        return h('div', {
          class: 'channel-card',
          'data-disabled': String(!isChecked),
          style: { cursor: 'pointer' },
          onClick: toggleSoilChannel,
        },
        h('div', {
          class: 'channel-head',
          ...(isChecked ? { 'data-active': '' } : {}),
        },
        toggleUi,
        h('div', { style: { flex: '1', minWidth: '0' } },
          h('div', { class: 'ch-title' }, s.name),
          h('div', { class: 'hint', style: { fontSize: '11px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, `${typeLabel} · ${s.entity_id}`)),
        h('span', { class: 'badge-tag' }, liveVal)));
      }

      const card = h('div', {
        class: 'channel-card',
        style: s.type === 'ignore' ? { opacity: '0.55' } : {},
      });

      const autoBadge = (s.type === s.detectedType && s.type !== 'ignore')
        ? h('span', { class: 'badge-tag ok auto-badge' }, icon('mdi:check-circle'), 'Auto')
        : null;

      const effectivePlac = s.placement || this.sensorPlacement || 'room';
      const placementDd = new CustomDropdown({
        options: [
          { value: 'room', label: 'Raum-Statusleiste', icon: 'mdi:dock-bottom' },
          { value: 'tile', label: 'Eigene Gerätekachel', icon: 'mdi:card-outline' },
        ],
        value: effectivePlac,
        onChange: (val) => {
          s.placement = val;
        },
      });
      this._dropdowns.push(placementDd);
      const placementField = h('div', { class: 'field', ...(s.type === 'ignore' ? { hidden: true } : {}) },
        h('div', { class: 'field-head' }, h('span', { class: 'field-label' }, 'Darstellung im Raum')),
        placementDd.el);

      const typeDd = new CustomDropdown({
        options: ROOM_SENSOR_TYPES,
        value: s.type,
        onChange: (val) => {
          s.type = val;
          card.style.opacity = val === 'ignore' ? '0.55' : '';
          placementField.hidden = val === 'ignore';
          if (autoBadge) {
            autoBadge.hidden = val !== s.detectedType || val === 'ignore';
          }
        },
      });
      this._dropdowns.push(typeDd);

      card.append(
        h('div', { style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px', marginBottom: '8px', flexWrap: 'wrap' } },
          h('div', { style: { minWidth: '0', flex: '1' } },
            h('div', { style: { fontWeight: '600', fontSize: '14px' } }, s.name),
            h('div', { class: 'hint', style: { fontSize: '11px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, s.entity_id)),
          h('div', { style: { display: 'flex', alignItems: 'center', gap: '6px' } },
            autoBadge,
            h('span', { class: 'badge-tag' }, liveVal))),
        h('div', { class: 'fields' },
          h('div', { class: 'field' },
            h('div', { class: 'field-head' }, h('span', { class: 'field-label' }, 'Sensortyp')),
            typeDd.el),
          placementField));

      return card;
    });

    return h('div', { style: { marginTop: '14px' } },
      soilPlacementRow,
      h('div', { class: 'section-title' }, isSoil ? 'Messwerte & Kanäle' : 'Raumsensoren'),
      h('div', { class: 'hint', style: { marginBottom: '8px' } }, isSoil ? 'Gewünschte Bodenwerte aktivieren' : 'Typ & Darstellung für Raum wählen'),
      ...cards);
  }

  // ═══════════════ STEP 2: Kanäle & Messung ═══════════════
  _renderStep2() {
    this._cleanupDropdowns();
    const isMulti = this.channels.length > 1;
    const sensorSection = this._buildSensorSection();

    if (!this.channels.length && !sensorSection) {
      this.body.replaceChildren(h('div', { class: 'empty' },
        icon('mdi:alert-circle-outline'),
        h('div', { style: { fontWeight: '600' } }, 'Keine Entitäten'),
        h('div', { class: 'hint' }, 'Keine passenden Kanäle/Sensoren')));
      return;
    }

    const curCat = DEVICE_CATEGORIES.find((c) => c.id === this.selectedCategory) || DEVICE_CATEGORIES[0];
    const hero = h('div', { class: 'win11-hero-badge', style: { color: curCat.color || 'var(--cd-accent)', '--hero-color': curCat.color || 'var(--cd-accent)' } }, icon(curCat.icon || 'mdi:tune-vertical'));

    const header = h('div', { style: { textAlign: 'center', marginBottom: '8px' } },
      h('h3', { style: { margin: '0 0 2px', fontSize: '17px', fontWeight: '700' } },
        !this.channels.length ? 'Raumsensoren' : (isMulti ? 'Kanäle & Messung' : 'Messung & Simulation')),
      h('div', { class: 'hint' },
        !this.channels.length
          ? 'Sensortyp für Raumkachel'
          : (isMulti ? 'Kanäle einzeln zuordnen' : 'Leistung, Energie & Simulation')));

    if (!this.channels.length) {
      this.body.replaceChildren(hero, header, sensorSection);
      return;
    }

    const devEntityIds = new Set(
      (this.entities || [])
        .filter((e) => (this.selectedDevice?.isVirtualEntity ? e.entity_id === this.selectedDevice.entity_id : e.device_id === this.selectedDevice?.id))
        .map((e) => e.entity_id),
    );
    const isPowerSensor = (_eid, st) => {
      const dc = String(st?.attributes?.device_class || '').toLowerCase();
      const u = String(st?.attributes?.unit_of_measurement || '').toLowerCase();
      return dc === 'power' || ['w', 'kw', 'mw'].includes(u);
    };
    const isEnergySensor = (_eid, st) => {
      const dc = String(st?.attributes?.device_class || '').toLowerCase();
      const u = String(st?.attributes?.unit_of_measurement || '').toLowerCase();
      return dc === 'energy' || ['kwh', 'wh', 'mwh'].includes(u);
    };

    if (!isMulti) {
      const ch = this.channels[0];

      const powerPicker = new EntityPicker({
        hass: this.hass,
        value: ch.power || '',
        placeholder: 'Watt-Sensor (optional)',
        domain: 'sensor',
        priorityEntityIds: devEntityIds,
        filter: isPowerSensor,
        onChange: (val) => {
          ch.power = val;
          this.powerEntityId = val;
        },
      });
      this._dropdowns.push(powerPicker);

      const isAutoPower = ch.power && ch.power === this.powerEntityId;
      const powerBadge = isAutoPower
        ? h('span', { class: 'badge-tag ok auto-badge', style: { marginLeft: '8px' } }, icon('mdi:check-circle'), 'Auto')
        : null;

      const powerCard = h('div', { class: 'row-card', style: { padding: '14px 16px', gap: '10px' } },
        h('div', { style: { display: 'flex', alignItems: 'center', gap: '10px' } },
          h('div', { class: 'feature-icon', style: { color: '#ffb74d', display: 'grid', placeItems: 'center', width: '36px', height: '36px', borderRadius: '8px', background: 'rgba(255,183,77,0.15)', flex: 'none' } }, icon('mdi:flash')),
          h('div', { style: { flex: '1', minWidth: '0' } },
            h('div', { style: { fontWeight: '600', fontSize: '14px', display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: '4px' } },
              'Leistung (Watt)', powerBadge),
            h('div', { class: 'hint', style: { marginTop: '2px' } }, 'Live-Verbrauch auf Kachel'))),
        powerPicker.el);

      const energyPicker = new EntityPicker({
        hass: this.hass,
        value: ch.energy || '',
        placeholder: 'kWh-Sensor (optional)',
        domain: 'sensor',
        priorityEntityIds: devEntityIds,
        filter: isEnergySensor,
        onChange: (val) => {
          ch.energy = val;
          this.energyEntityId = val;
        },
      });
      this._dropdowns.push(energyPicker);

      const isAutoEnergy = ch.energy && ch.energy === this.energyEntityId;
      const energyBadge = isAutoEnergy
        ? h('span', { class: 'badge-tag ok auto-badge', style: { marginLeft: '8px' } }, icon('mdi:check-circle'), 'Auto')
        : null;

      const energyCard = h('div', { class: 'row-card', style: { padding: '14px 16px', gap: '10px' } },
        h('div', { style: { display: 'flex', alignItems: 'center', gap: '10px' } },
          h('div', { class: 'feature-icon', style: { color: '#66bb6a', display: 'grid', placeItems: 'center', width: '36px', height: '36px', borderRadius: '8px', background: 'rgba(102,187,106,0.15)', flex: 'none' } }, icon('mdi:lightning-bolt')),
          h('div', { style: { flex: '1', minWidth: '0' } },
            h('div', { style: { fontWeight: '600', fontSize: '14px', display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: '4px' } },
              'Energie (kWh)', energyBadge),
            h('div', { class: 'hint', style: { marginTop: '2px' } }, 'Gesamtverbrauch (kWh / Wh)'))),
        energyPicker.el);

      const simCard = h('div', {
        class: `feature-card${ch.presence_simulation ? ' active' : ''}`,
        style: { '--feat-color': '#ba68c8', cursor: 'pointer' },
        ...(ch.presence_simulation ? { 'data-active': '' } : {}),
        onClick: () => {
          ch.presence_simulation = !ch.presence_simulation;
          simCard.toggleAttribute('data-active', ch.presence_simulation);
          simCard.classList.toggle('active', ch.presence_simulation);
        },
      },
      h('div', { class: 'feature-icon' }, icon('mdi:home-clock')),
      h('div', { class: 'feature-info' },
        h('div', { class: 'feature-title' }, 'Anwesenheitssimulation'),
        h('div', { class: 'feature-desc' }, 'Zufallsschalten bei Abwesenheit')),
      h('div', { class: 'switch-ui' }));

      this.body.replaceChildren(...[hero, header, powerCard, energyCard, simCard, sensorSection].filter(Boolean));
      return;
    }

    // MULTI-CHANNEL DEVICE (e.g. Shelly 2PM / 4-Kanal Wasserventil)
    const catOptions = DEVICE_CATEGORIES.map((c) => ({
      value: c.id, label: c.name, icon: c.icon, color: c.color,
    }));
    const chAreaOptions = [
      { value: '', label: 'Wie Gerät (Standard)', icon: 'mdi:home-outline' },
      ...this.areas.map((a) => ({ value: a.area_id, label: a.name, icon: this._getRoomIcon(a) })),
    ];

    const mkModeCard = (val, ic, title, desc) => {
      const active = this.displayMode === val;
      return h('div', {
        class: `cat-card${active ? ' active' : ''}`,
        style: { '--cat-color': 'var(--cd-accent, #29b6f6)', flex: '1 1 160px', minWidth: '0', textAlign: 'left', padding: '10px 12px', display: 'flex', alignItems: 'center', gap: '10px' },
        ...(active ? { 'data-selected': '' } : {}),
        onClick: () => {
          this.displayMode = val;
          preserveScroll(this.body, () => this._renderStep2());
        },
      },
      icon(ic),
      h('div', { style: { minWidth: '0' } },
        h('div', { style: { fontWeight: '600', fontSize: '13px' } }, title),
        h('div', { class: 'hint', style: { fontSize: '11px' } }, desc)));
    };

    const displayModeBlock = h('div', { style: { marginBottom: '12px' } },
      h('div', { class: 'section-title' }, 'Darstellung im Dashboard'),
      h('div', { style: { display: 'flex', gap: '8px', flexWrap: 'wrap' } },
        mkModeCard('individual', 'mdi:view-grid-outline', 'Einzelne Kacheln', 'Eigener Name & optional eigener Raum'),
        mkModeCard('bundled', 'mdi:view-sequential-outline', 'Gebündelt in Kachel', 'Alle Kanäle in einer Kachel')));

    const channelCards = this.channels.map((ch, idx) => {
      const nameInput = h('input', {
        type: 'text', value: ch.name, placeholder: `Kanal ${idx + 1}`, disabled: !ch.enabled,
        onInput: (e) => { ch.name = e.target.value; },
      });

      const catDropdown = new CustomDropdown({
        options: catOptions,
        value: ch.category,
        disabled: !ch.enabled,
        onChange: (val) => { ch.category = val; },
      });
      this._dropdowns.push(catDropdown);

      let areaField = null;
      if (this.displayMode !== 'bundled') {
        const areaDd = new CustomDropdown({
          options: chAreaOptions,
          value: ch.area_id || '',
          disabled: !ch.enabled,
          onChange: (val) => { ch.area_id = val; },
        });
        this._dropdowns.push(areaDd);
        areaField = h('div', { class: 'field' },
          h('div', { class: 'field-head' }, h('span', { class: 'field-label' }, 'Raum (optional)')),
          areaDd.el);
      }

      const powerPicker = new EntityPicker({
        hass: this.hass,
        value: ch.power || '',
        placeholder: 'Watt-Sensor (optional)',
        domain: 'sensor',
        priorityEntityIds: devEntityIds,
        filter: isPowerSensor,
        onChange: (val) => { ch.power = val; },
      });
      this._dropdowns.push(powerPicker);

      const energyPicker = new EntityPicker({
        hass: this.hass,
        value: ch.energy || '',
        placeholder: 'kWh-Sensor (optional)',
        domain: 'sensor',
        priorityEntityIds: devEntityIds,
        filter: isEnergySensor,
        onChange: (val) => { ch.energy = val; },
      });
      this._dropdowns.push(energyPicker);

      const simCard = h('div', {
        class: `feature-card${ch.presence_simulation && ch.enabled ? ' active' : ''}`,
        style: { '--feat-color': '#ba68c8', cursor: ch.enabled ? 'pointer' : 'default' },
        ...(ch.presence_simulation && ch.enabled ? { 'data-active': '' } : {}),
        onClick: () => {
          if (!ch.enabled) return;
          ch.presence_simulation = !ch.presence_simulation;
          simCard.toggleAttribute('data-active', ch.presence_simulation);
          simCard.classList.toggle('active', ch.presence_simulation);
        },
      },
      h('div', { class: 'feature-icon' }, icon('mdi:home-clock')),
      h('div', { class: 'feature-info' },
        h('div', { class: 'feature-title' }, 'Anwesenheitssimulation'),
        h('div', { class: 'feature-desc' }, 'Zufallsschalten bei Abwesenheit')),
      h('div', { class: 'switch-ui' }));

      const isAutoPower = ch.power && (ch.power === this.powerEntityId || ch.power === ch._autoPower);
      const powerBadge = isAutoPower
        ? h('span', { class: 'badge-tag ok auto-badge' }, icon('mdi:check-circle'), 'Auto')
        : null;

      const isAutoEnergy = ch.energy && (ch.energy === this.energyEntityId || ch.energy === ch._autoEnergy);
      const energyBadge = isAutoEnergy
        ? h('span', { class: 'badge-tag ok auto-badge' }, icon('mdi:check-circle'), 'Auto')
        : null;

      const enabledToggle = h('div', {
        class: 'switch-ui',
        ...(ch.enabled ? { 'data-active': '' } : {}),
        style: { cursor: 'pointer' },
        onClick: (e) => {
          e.stopPropagation();
          ch.enabled = !ch.enabled;
          preserveScroll(this.body, () => this._renderStep2());
        },
      });

      const pendingBadge = !ch.enabled || ch.wasPending
        ? h('span', { class: 'badge-tag pending-channels' }, !ch.enabled ? 'Übersprungen' : 'Offen')
        : null;

      const headCard = h('div', {
        class: 'channel-head',
        ...(ch.enabled ? { 'data-active': '' } : {}),
        style: { cursor: 'pointer' },
        onClick: () => {
          ch.enabled = !ch.enabled;
          preserveScroll(this.body, () => this._renderStep2());
        },
      },
      enabledToggle,
      h('div', { class: 'ch-title' }, ch.name || ch.entity_id),
      pendingBadge,
      h('span', { class: 'badge-tag' }, ch.entity_id));

      return h('div', { class: 'channel-card', 'data-disabled': String(!ch.enabled) },
        headCard,
        h('div', { class: 'fields' },
          h('div', { class: 'field' },
            h('div', { class: 'field-head' }, h('span', { class: 'field-label' }, 'Kanalname')),
            nameInput),
          h('div', { class: 'field' },
            h('div', { class: 'field-head' }, h('span', { class: 'field-label' }, 'Kategorie')),
            catDropdown.el),
          areaField,
          h('div', { class: 'field' },
            h('div', { class: 'field-head' },
              h('span', { class: 'field-label' }, 'Leistung (Watt)'),
              powerBadge),
            powerPicker.el),
          h('div', { class: 'field' },
            h('div', { class: 'field-head' },
              h('span', { class: 'field-label' }, 'Energie (kWh)'),
              energyBadge),
            energyPicker.el)),
        simCard);
    });

    this.body.replaceChildren(...[hero, header, displayModeBlock, ...channelCards, sensorSection].filter(Boolean));
  }

  // ═══════════════ STEP 3: Prüfen & Speichern ═══════════════
  _renderStep3() {
    const area = this.areas.find((a) => a.area_id === this.selectedAreaId);
    const areaName = area?.name || 'Kein Raum';
    const cat = DEVICE_CATEGORIES.find((c) => c.id === this.selectedCategory) || DEVICE_CATEGORIES[0];
    const activeChannels = this.channels.filter((c) => c.enabled);

    const hero = h('div', { class: 'win11-hero-badge', style: { color: cat.color, '--hero-color': cat.color } }, icon(cat.icon || 'mdi:check-circle'));

    const header = h('div', { style: { textAlign: 'center', marginBottom: '10px' } },
      h('h3', { style: { margin: '0 0 2px', fontSize: '17px', fontWeight: '700' } }, 'Prüfen'),
      h('div', { class: 'hint' }, 'Auswahl kontrollieren & speichern'));

    const hasSim = activeChannels.some((c) => c.presence_simulation);
    const hasPower = activeChannels.some((c) => c.power);
    const hasEnergy = activeChannels.some((c) => c.energy);
    const areaBadgeIcon = this.selectedAreaId ? this._getRoomIcon(this.selectedAreaId) : 'mdi:map-marker-off';

    const previewCard = h('div', {
      class: 'win11-preview-card',
      style: { '--preview-color': cat.color },
    },
    h('div', { class: 'win11-preview-icon' }, icon(this.customIcon || cat.icon)),
    h('div', { class: 'win11-preview-info' },
      h('div', { class: 'win11-preview-name' }, this.customName || 'Gerät'),
      h('div', { class: 'win11-preview-meta' },
        h('span', { class: 'badge-tag category', style: { '--badge-cat-color': cat.color } }, icon(cat.icon), cat.name),
        h('span', { class: 'badge-tag area' }, icon(areaBadgeIcon), areaName),
        hasPower ? h('span', { class: 'badge-tag', style: { color: '#ffb74d' } }, icon('mdi:flash'), 'Leistung') : null,
        hasEnergy ? h('span', { class: 'badge-tag', style: { color: '#66bb6a' } }, icon('mdi:lightning-bolt'), 'Energie') : null,
        this.forceOwnRow ? h('span', { class: 'badge-tag' }, icon('mdi:view-agenda-outline'), 'Eigene Zeile') : null,
        hasSim ? h('span', { class: 'badge-tag', style: { color: '#ce93d8' } }, icon('mdi:home-clock'), 'Simulation') : null)));

    const syncCard = h('div', {
      class: `feature-card${this.renameInHA ? ' active' : ''}`,
      style: { '--feat-color': '#2196f3', cursor: 'pointer' },
      ...(this.renameInHA ? { 'data-active': '' } : {}),
      onClick: () => {
        this.renameInHA = !this.renameInHA;
        syncCard.toggleAttribute('data-active', this.renameInHA);
        syncCard.classList.toggle('active', this.renameInHA);
      },
    },
    h('div', { class: 'feature-icon' }, icon('mdi:home-assistant')),
    h('div', { class: 'feature-info' },
      h('div', { class: 'feature-title' }, 'HA-Synchronisierung'),
      h('div', { class: 'feature-desc' }, 'Name & Raum in HA übernehmen')),
    h('div', { class: 'switch-ui' }));

    const syncAccordion = h('details', { class: 'adv-options' },
      h('summary', {}, icon('mdi:cog-outline'), 'Optionen: HA-Sync'),
      h('div', { class: 'adv-content' }, syncCard));

    let hybridSection = null;
    const d = this.selectedDevice;
    if (this._activeHybridCfg) {
      const masterCh = (this._activeHybridCfg.channels || [])[0];
      const masterEid = masterCh?.master_entity_id || this.channels[0]?.entity_id;
      const activeProto = masterEid ? this.hass?.states?.[masterEid]?.attributes?.active_transport : null;
      const protoTxt = activeProto === 'zigbee' ? 'Zigbee' : activeProto === 'matter' ? 'Matter' : activeProto === 'wlan' ? 'WLAN' : 'Automatisch';
      const globalPref = this.hybridSettings?.preferred_protocol || 'zigbee';
      const globalLabel = globalPref === 'zigbee' ? 'Zigbee' : globalPref === 'matter' ? 'Matter' : 'WLAN';

      const prefDd = new CustomDropdown({
        options: [
          { value: '', label: `Global (${globalLabel})`, icon: 'mdi:earth' },
          { value: 'zigbee', label: 'Zigbee', icon: 'mdi:zigbee' },
          { value: 'matter', label: 'Matter', icon: 'mdi:hub' },
          { value: 'wlan', label: 'WLAN', icon: 'mdi:wifi' },
        ],
        value: this._hybridPreferredProtocol || '',
        onChange: (val) => { this._hybridPreferredProtocol = val || ''; },
      });
      this._dropdowns.push(prefDd);

      hybridSection = h('div', { style: { display: 'grid', gap: '8px', marginTop: '6px' } },
        h('div', { class: 'row-card', style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px' } },
          h('div', { style: { display: 'flex', alignItems: 'center', gap: '8px' } },
            icon('mdi:swap-horizontal-bold'),
            h('span', { style: { fontWeight: '600', fontSize: '13px' } }, 'Aktiver Funkweg')),
          h('span', { class: 'badge-tag hybrid' }, protoTxt)),
        h('details', { class: 'adv-options' },
          h('summary', {}, icon('mdi:tune'), 'Hybrid-Optionen: Funkweg & Trennung'),
          h('div', { class: 'adv-content', style: { display: 'grid', gap: '10px' } },
            h('div', { class: 'field' }, 'Bevorzugter Funkweg (Gerät)', prefDd.el),
            h('button', {
              type: 'button',
              class: 'btn danger small',
              onClick: () => this._unpairHybrid(this._activeHybridCfg),
            }, icon('mdi:link-off'), 'Hybrid-Verknüpfung trennen'))));
    } else if (d && !d.isVirtualEntity && !isHybridMasterDevice(d) && this.configuredDevices?.[d.id]) {
      hybridSection = h('div', { class: 'row-card', style: { marginTop: '6px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px', flexWrap: 'wrap' } },
        h('div', {},
          h('div', { style: { fontWeight: '600', fontSize: '13px' } }, 'Multi-Protokoll-Erweiterung'),
          h('div', { class: 'hint' }, '• Zweiten Funkweg (Zigbee/WLAN/Matter) verknüpfen')),
        h('button', {
          type: 'button',
          class: 'btn secondary small',
          onClick: () => this._openHybridModal({ baseDevice: d, baseConfig: this.configuredDevices[d.id] }),
        }, icon('mdi:swap-horizontal-bold'), 'Als Hybrid erweitern'));
    }

    const channelSummary = this.channels.length > 1
      ? h('div', { class: 'row-card', style: { marginTop: '8px' } },
        h('div', { style: { fontWeight: '600', fontSize: '13px' } }, `Kanäle (${activeChannels.length})`),
        h('div', { class: 'hint' }, activeChannels.map((c) => {
          const cCat = DEVICE_CATEGORIES.find((catItem) => catItem.id === c.category);
          return `• ${c.name} (${cCat?.name || c.category})`;
        }).join('\n')))
      : null;

    const items = [
      hero,
      header,
      previewCard,
      channelSummary,
      hybridSection,
      syncAccordion,
    ].filter(Boolean);

    this.body.replaceChildren(...items);
  }

  // ═══════════════ POST-SAVE CELEBRATION ═══════════════
  _renderCelebration() {
    this._cleanupDropdowns();
    this.selectionSlot.replaceChildren();
    this.stepBar.hidden = true;
    this.foot.hidden = true;
    this.dialog.style.setProperty('--hero-color', '#10b981');

    const area = this.areas.find((a) => a.area_id === this.selectedAreaId);
    const areaName = area?.name || 'Dashboard';

    const celebration = h('div', { class: 'win11-celebration' },
      h('div', { class: 'win11-success-badge' }, icon('mdi:check')),
      h('h2', { style: { margin: '6px 0 2px', fontSize: '20px', fontWeight: '700', color: 'var(--primary-text-color, inherit)' } }, 'Fertig'),
      h('div', { class: 'hint', style: { fontSize: '14px', maxWidth: '400px' } },
        `„${this.customName}“ · ${areaName}`),
      h('div', { style: { display: 'flex', gap: '10px', marginTop: '14px', flexWrap: 'wrap', justifyContent: 'center' } },
        this.directMode ? null : h('button', {
          class: 'btn secondary',
          onClick: async () => {
            this.isCelebration = false;
            this.step = 0;
            this.selectedDevice = null;
            this.selectedDevices.clear();
            this._expandedDeviceChannels.clear();
            await this._load({ preserveStep0: true });
          },
        }, icon('mdi:plus'), 'Weiteres Gerät'),
        h('button', {
          class: 'btn primary',
          onClick: () => {
            this._closeWizard();
            this.onSaved(null);
          },
        }, icon(this.directMode ? 'mdi:check' : 'mdi:view-dashboard'), this.directMode ? 'Fertig' : 'Dashboard')));

    this.body.replaceChildren(celebration);
  }

  _renderBody() {
    switch (this.step) {
      case 0: return this._renderStep0();
      case 1: return this._renderStep1();
      case 2: return this._renderStep2();
      case 3: return this._renderStep3();
      default: return null;
    }
  }

  // ═══════════════ Speichern ═══════════════
  async _save() {
    if (this._saving) return;
    this._saving = true;
    this._renderFoot();

    const d = this.selectedDevice;
    const isMultiDevice = this.channels.length > 1;
    const activeChannels = this.channels.filter((c) => c.enabled);
    const isMulti = isMultiDevice || activeChannels.length > 1;

    try {
      // 1. Rename in Home Assistant if checked
      if (this.renameInHA && d) {
        if (!d.isVirtualEntity) {
          try {
            await this.hass.callWS({
              type: 'config/device_registry/update',
              device_id: d.id,
              name_by_user: this.customName || undefined,
              area_id: this.selectedAreaId || null,
            });
          } catch (err) {
            console.warn('[wizard] device rename failed', err);
          }
        } else if (d.entity_id) {
          try {
            await this.hass.callWS({
              type: 'config/entity_registry/update',
              entity_id: d.entity_id,
              name: this.customName || undefined,
              area_id: this.selectedAreaId || null,
            });
          } catch (err) {
            console.warn('[wizard] virtual entity update failed', err);
          }
        }

        // Entity renames (only set name for multi-channel entities; keep single-channel Friendly Name intact)
        for (const ch of activeChannels) {
          try {
            const entEntry = this.entities.find((e) => e.entity_id === ch.entity_id);
            const payload = {
              type: 'config/entity_registry/update',
              entity_id: ch.entity_id,
              area_id: (this.displayMode !== 'bundled' && ch.area_id) ? ch.area_id : (this.selectedAreaId || null),
            };
            if (ch._wasDisabledByUser || entEntry?.disabled_by === 'user') {
              payload.disabled_by = null;
              if (entEntry) entEntry.disabled_by = null;
            }
            if (isMultiDevice && ch.name) {
              payload.name = ch.name;
            }
            await this.hass.callWS(payload);
          } catch (err) {
            console.warn('[wizard] entity rename failed', err);
          }
        }
      } else {
        for (const ch of activeChannels) {
          const entEntry = this.entities.find((e) => e.entity_id === ch.entity_id);
          if (ch._wasDisabledByUser || entEntry?.disabled_by === 'user') {
            try {
              await this.hass.callWS({
                type: 'config/entity_registry/update',
                entity_id: ch.entity_id,
                disabled_by: null,
              });
              if (entEntry) entEntry.disabled_by = null;
            } catch (err) {
              console.warn('[wizard] entity re-enable failed', err);
            }
          }
        }
      }

      // 2. Configure in Companion Store
      let entitiesConfig = {};
      if (isMultiDevice) {
        const sub_entities = {};
        let firstId = null;
        let firstUid = null;
        for (const ch of this.channels) {
          if (ch.enabled && !firstId) {
            firstId = ch.entity_id;
            firstUid = ch.unique_id;
          }
          sub_entities[ch.entity_id] = {
            enabled: !!ch.enabled,
            category: ch.category,
            custom_name: ch.name,
            name: ch.name,
            area_id: this.displayMode !== 'bundled' ? (ch.area_id || undefined) : undefined,
            icon: this.customIcon || undefined,
            original_id: ch.entity_id,
            unique_id: ch.unique_id,
            power: ch.power || undefined,
            energy: ch.energy || undefined,
            presence_simulation: ch.presence_simulation || false,
            force_own_row: !!this.forceOwnRow,
          };
        }
        entitiesConfig = {
          primary: firstId || this.channels[0]?.entity_id,
          primary_unique_id: firstUid || this.channels[0]?.unique_id,
          sub_entities,
        };
      } else {
        const primary = activeChannels[0] || this.channels[0];
        const fallbackPrimaryId = primary?.entity_id
          || (this.selectedCategory === 'rauchmelder' ? (this.primaryEntityId || this.smokeEntityId) : undefined)
          || (this.selectedCategory === 'solar' ? (this.powerEntityId || this.energyEntityId || this.sensorEntities.find((s) => s.type !== 'ignore')?.entity_id) : undefined)
          || (this.selectedCategory === 'bodenmessgeraet' && this.sensorPlacement === 'tile'
            ? (this.sensorEntities.find((s) => s.type === 'moisture')?.entity_id || this.sensorEntities.find((s) => s.type !== 'ignore')?.entity_id)
            : undefined)
          || (this.selectedCategory === 'raummessgeraet' && this.sensorPlacement === 'tile'
            ? (this.sensorEntities.find((s) => s.type === 'temperature')?.entity_id || this.sensorEntities.find((s) => s.type !== 'ignore')?.entity_id)
            : undefined)
          || (this.selectedCategory === 'bewegungsmelder' && this.sensorPlacement === 'tile'
            ? (this.sensorEntities.find((s) => s.type === 'motion')?.entity_id || this.sensorEntities.find((s) => s.type !== 'ignore')?.entity_id)
            : undefined);
        const fallbackPrimaryEnt = fallbackPrimaryId ? this.entities.find((e) => e.entity_id === fallbackPrimaryId) : null;
        entitiesConfig = {
          primary: fallbackPrimaryId,
          primary_unique_id: primary?.unique_id || fallbackPrimaryEnt?.unique_id,
          power: primary?.power || undefined,
          energy: primary?.energy || undefined,
          presence_simulation: primary?.presence_simulation || false,
        };
      }

      const room_sensors = {};
      for (const s of (this.sensorEntities || [])) {
        room_sensors[s.entity_id] = {
          entity_id: s.entity_id,
          unique_id: s.unique_id || undefined,
          original_id: s.entity_id,
          type: s.type,
          enabled: s.type !== 'ignore',
          ...(s.placement ? { placement: s.placement } : {}),
        };
      }
      entitiesConfig.room_sensors = room_sensors;

      const existingOpts = this.configuredDevices?.[d.id]?.options || {};
      const nextOptions = {
        ...existingOpts,
        force_own_row: !!this.forceOwnRow,
        pinned: !!this.pinned,
      };
      if (isMultiDevice) {
        nextOptions.display_mode = this.displayMode;
      }
      if (['bodenmessgeraet', 'rauchmelder', 'raummessgeraet', 'bewegungsmelder'].includes(this.selectedCategory)) {
        nextOptions.sensor_placement = this.sensorPlacement || (['bodenmessgeraet', 'rauchmelder'].includes(this.selectedCategory) ? 'tile' : 'room');
      }

      if (this.selectedCategory === 'rauchmelder' && (this.smokeEntityId || entitiesConfig.primary)) {
        const smokeId = this.smokeEntityId || entitiesConfig.primary;
        const smokeEnt = this.entities.find((e) => e.entity_id === smokeId);
        entitiesConfig.room_sensors[smokeId] = {
          entity_id: smokeId,
          unique_id: smokeEnt?.unique_id || undefined,
          original_id: smokeId,
          type: 'smoke',
          enabled: true,
        };
      }

      const res = await this.hass.callWS({
        type: 'smarthome_companion/devices/configure',
        device_id: d.id,
        category: this.selectedCategory,
        custom_name: this.customName,
        area_id: this.selectedAreaId || '',
        icon: this.customIcon || undefined,
        options: nextOptions,
        entities: entitiesConfig,
      });

      if (res?.save_failed) throw new Error('Speichern im Backend fehlgeschlagen');

      if (this._activeHybridCfg) {
        const nextPref = this._hybridPreferredProtocol || null;
        const curPref = this._activeHybridCfg.preferred_protocol || null;
        if (nextPref !== curPref || this.customName !== this._activeHybridCfg.name || (this.selectedAreaId || '') !== (this._activeHybridCfg.area_id || '')) {
          await this.hass.callWS({
            type: 'smarthome_companion/hybrids/save',
            hybrid_id: this._activeHybridCfg.id,
            name: this.customName,
            area_id: this.selectedAreaId || '',
            category: this.selectedCategory,
            icon: this.customIcon || null,
            preferred_protocol: nextPref,
          }).catch((e) => console.warn('[wizard] hybrid sync update failed', e));
        }
      }

      // Persist pin state on dashboard config (for dev:<id> or entity:<id>)
      const pinKey = d.isVirtualEntity ? d.id : `dev:${d.id}`;
      try {
        await this.hass.callWS({
          type: 'smarthome_companion/dashboard/tile_order',
          area_id: this.selectedAreaId || '__none__',
          pin_key: pinKey,
          pinned: !!this.pinned,
        });
        const curPins = Array.isArray(this._dashboardConfig?.pinned_tiles) ? [...this._dashboardConfig.pinned_tiles] : [];
        if (this.pinned && !curPins.includes(pinKey)) curPins.push(pinKey);
        if (!this.pinned) {
          this._dashboardConfig = { ...(this._dashboardConfig || {}), pinned_tiles: curPins.filter((k) => k !== pinKey) };
        } else {
          this._dashboardConfig = { ...(this._dashboardConfig || {}), pinned_tiles: curPins };
        }
      } catch (pinErr) {
        console.warn('[wizard] pin update failed', pinErr);
      }

      // Optimistic cache update so returning to Step 0 immediately reflects the configured device
      this.configuredDevices[d.id] = {
        device_id: d.id,
        category: this.selectedCategory,
        custom_name: this.customName,
        area_id: this.selectedAreaId || '',
        icon: this.customIcon || undefined,
        options: nextOptions,
        entities: entitiesConfig,
      };

      // Save room icon for newly populated room if selected
      if (this.selectedAreaId && this.roomIcon && this._isNewRoomForDevice(this.selectedAreaId)) {
        try {
          await this.hass.callWS({
            type: 'config/area_registry/update',
            area_id: this.selectedAreaId,
            icon: this.roomIcon,
          });
        } catch (_) { /* non-fatal in mock/dev mode */ }
        try {
          const dashData = await this.hass.callWS({ type: 'smarthome_companion/dashboard/get', edit: true });
          const cfg = dashData?.config || {};
          cfg.rooms ||= {};
          cfg.rooms[this.selectedAreaId] ||= {};
          cfg.rooms[this.selectedAreaId].icon = this.roomIcon;
          await this.hass.callWS({ type: 'smarthome_companion/dashboard/save', config: cfg });
        } catch (_) { /* non-fatal */ }
      }

      // Check for dynamic sensor conflicts in the target room
      const activeTypes = [...new Set((this.sensorEntities || [])
        .filter((s) => s.type && s.type !== 'ignore')
        .map((s) => s.type))];

      if (this.selectedAreaId && activeTypes.length > 0) {
        try {
          const updatedDash = await this.hass.callWS({ type: 'smarthome_companion/dashboard/get', edit: true });
          const room = updatedDash?.layout?.rooms?.find((r) => r.area_id === this.selectedAreaId);
          const conflicts = activeTypes
            .map((t) => ({ type: t, entityIds: room?.all_sensors?.[t] || [] }))
            .filter((c) => c.entityIds.length > 1);

          if (conflicts.length > 0) {
            this._saving = false;
            this.dialog.hidden = true;
            const conflictModal = new SensorConflictModal({
              hass: this.hass,
              areaName: room?.name || 'Raum',
              conflicts,
              currentPrefs: room?.sensor_prefs || {},
              onSave: async (prefs) => {
                const cfg = updatedDash?.config || {};
                cfg.rooms ||= {};
                cfg.rooms[this.selectedAreaId] ||= {};
                cfg.rooms[this.selectedAreaId].sensor_prefs = prefs;
                await this.hass.callWS({ type: 'smarthome_companion/dashboard/save', config: cfg });
                if (this.directMode) {
                  this.onClose();
                  this.onSaved(null);
                } else {
                  this.dialog.hidden = false;
                  this.isCelebration = true;
                  this._renderCelebration();
                }
              },
              onCancel: () => {
                if (this.directMode) {
                  this.onClose();
                  this.onSaved(null);
                } else {
                  this.dialog.hidden = false;
                  this.isCelebration = true;
                  this._renderCelebration();
                }
              },
            });
            this.el.append(conflictModal.el);
            return;
          }
        } catch (err) {
          console.warn('[wizard] conflict check failed', err);
        }
      }

      this._saving = false;
      if (this.directMode) {
        this.onClose();
        this.onSaved(null);
      } else {
        this.isCelebration = true;
        this._renderCelebration();
      }
    } catch (err) {
      this._saving = false;
      this._renderFoot();
      this.onSaved(err);
    }
  }
}
